YH_EXAM_BANKS["GS151-U"] = {"id":"GS151-U","course":"GS 151","short":"الوحدات ١–٣","lang":"ar","version":1,"los":[{"lo":"U1","ar":"مهارات تحديد الأهداف الحياتية","en":""},{"lo":"U2","ar":"مهارات إدارة الوقت وتنظيمه","en":""},{"lo":"U3","ar":"مهارات حل المشكلات واتخاذ القرارات","en":""}],"sections":{"GS151-U1":{"ar":"الوحدة الأولى — مهارات تحديد الأهداف الحياتية"},"GS151-U2":{"ar":"الوحدة الثانية — مهارات إدارة الوقت وتنظيمه"},"GS151-U3":{"ar":"الوحدة الثالثة — مهارات حل المشكلات واتخاذ القرارات"},"GS151-PRAC":{"ar":"الاختبار التجريبي — أسئلة الدكتور (الوحدات ١–٣)"}},"misconceptions":[{"id":"g1.umniya-vs-hulm","ar":"الأمنية والحلم نفس الشي","explain":"الأمنية ترغب فيها بس ما تحط لها برنامج عملي، والحلم ترغب فيه بس تستبعد إنه يصير وتظل متنقل بين الحلم والأمنية (ص 9).","fix":"الأمنية = بدون خطة. الحلم = تستبعد حدوثه. الهدف = مهم + خاص بك + تخطط لتنفيذه.","coach":"اسأل نفسك: شايفه ممكن بس ما خطط له؟ أمنية. شايفه بعيد ومستبعد؟ حلم.","sec":"GS151-U1"},{"id":"g1.ghaya-level","ar":"الغاية مجرد هدف عادي أو صغير","explain":"الغاية بالكتاب هي أعلى درجات الأهداف وأكثرها طموح (ص 9)، مو هدف عادي.","fix":"الغاية = القمة: أعلى درجة وأكثر طموح.","coach":"لو شفت «أعلى درجات» أو «أكثرها طموحاً» اختار الغاية على طول.","sec":"GS151-U1"},{"id":"g1.elements-vs-pillars","ar":"عناصر الهدف هي نفسها أركان التخطيط","explain":"عناصر الهدف 3: أمر مهم، خاص بك، تخطط لتنفيذه. أركان التخطيط 3: تحديد الغاية، تحديد الوسيلة، تحديد المعيار، وتحديد الهدف هو أول ركن (ص 8).","fix":"العناصر = وصف الهدف نفسه. الأركان = مراحل التخطيط.","coach":"كل الخيارات تبدأ بـ «تحديد...»؟ هذي أركان. فيها «أمر مهم / خاص بك»؟ هذي عناصر.","sec":"GS151-U1"},{"id":"g1.long-term-span","ar":"الطويل المدى أي هدف أكثر من 3 أو 5 سنوات","explain":"الطويل يزيد عن 10 سنوات ويسمونه أهداف العمر أو الأهداف المرحلية (ص 9)، وفي الخطوة الأولى يقدرونه من 10 لـ 20 سنة (ص 10). من 3 أو 5 لين 10 هذا المتوسط.","fix":"طويل = أكثر من 10. متوسط = 3 أو 5 : 10. قصير = أقل من 3.","coach":"احفظ الحدود: 3 و10. تحت 3 قصير، فوق 10 طويل، وبينهم متوسط.","sec":"GS151-U1"},{"id":"g1.short-vs-near","ar":"قصيرة المدى وقريبة المدى نفس المدة","explain":"قصيرة المدى في أنواع الأهداف = أقل من 3 سنوات (ص 9). قريبة المدى في خطوات وضع الأهداف = الخمس سنوات الجاية (ص 11).","fix":"قصيرة = أقل من 3 سنوات. قريبة = 5 سنوات.","coach":"شوف السؤال من وين: لو عن الخطوة الرابعة أو «قريبة» فالجواب 5 سنوات.","sec":"GS151-U1"},{"id":"g1.operational-todo","ar":"قوائم المهام للأهداف القصيرة أو المتوسطة","explain":"الأهداف الإجرائية أو التشغيلية هي الصغيرة اللي تصير أنشطة شهرية أو أسبوعية أو يومية ونكتبها في قوائم المهام To Do list (ص 9).","fix":"To Do list = إجرائية = تشغيلية.","coach":"يومي أو أسبوعي أو شهري + قائمة مهام = إجرائية على طول.","sec":"GS151-U1"},{"id":"g1.specific-vs-measurable","ar":"المحدد يعني الهدف فيه أرقام","explain":"المحدد يجاوب على 5Ws: Who, What, Where, When, Why (ص 12). القابل للقياس هو الكمي اللي فيه أرقام غالباً (ص 13).","fix":"محدد = 5Ws وما فيها How. قابل للقياس = أرقام وكمية.","coach":"شفت رقم أو كمية؟ قياس. شفت من/ماذا/أين/متى/لماذا؟ محدد.","sec":"GS151-U1"},{"id":"g1.attainable-vs-realistic","ar":"قابل للتحقيق وواقعي نفس المعنى","explain":"قابلية التحقيق تخص صاحب الهدف (مهاراته وقدراته والظروف الخارجية)، والواقعية تخص الهدف نفسه. كل هدف غير واقعي ما يتحقق، بس مو كل هدف واقعي يتحقق لأي شخص (ص 13).","fix":"Attainable = أنت وظروفك. Realistic = الهدف بحد ذاته.","coach":"لو الكلام عن قدراتك وظروفك اختار قابل للتحقيق، ولو عن الهدف نفسه اختار واقعي.","sec":"GS151-U1"},{"id":"g1.no-negation","ar":"عادي أكتب هدفي بالنفي مثل «ألا أتأخر»","explain":"ثاني ضابط من ضوابط الهدف: لا تستعمل النفي؛ قل «أن أفعل كذا» ولا تقول «أن لا أفعل كذا» (ص 13).","fix":"حوّل النفي لإثبات: «ألا أتأخر» تصير «أن أحضر في وقتي».","coach":"أي هدف فيه «لا» أو «ألا» أو «عدم» فيه خلل حسب الكتاب.","sec":"GS151-U1"},{"id":"g1.abc-priority","ar":"في أبجدية الأولويات (د) هو الأهم، أو صاحبها جورج دوران","explain":"أدوين بلس رتب الأولويات بأربعة حروف (أ – ب – جـ – د)؛ (أ) أكثرها أولوية و(د) أقلها، ولو تكرر الحرف ترقمه أ1، أ2 وتبدأ بـ أ1 (ص 13). جورج دوران صاحب SMART (ص 12).","fix":"بلس = الأبجدية. دوران = SMART. أ الأعلى، د الأقل.","coach":"الأبجدية تبدأ بـ أ، فالأهم يجي أول.","sec":"GS151-U1"},{"id":"g1.own-goals","ar":"ممكن أهلي أو غيري يحطون أهدافي ويتحملون تحقيقها","explain":"الكتاب يقول تأكد إنك أنت المسؤول عن أهدافك مو أحد تفوضه (ص 11)، ولا تخلي أحد يحط لك أهدافك لأنك أعرف الناس بقدراتك ورغباتك وطموحاتك (ص 14)، وحتى المرشد ما يقدر يحقق أهدافك عنك (ص 15).","fix":"أهدافك أنت تحطها وأنت مسؤول عنها. الرفيق والمرشد للمساعدة بس.","coach":"أي خيار فيه «غيرك يحطها أو يحققها عنك» غلط.","sec":"GS151-U1"},{"id":"g1.goals-flexible","ar":"الأهداف ثابتة ولازم أكملها مهما صار، والفشل نهاية","explain":"الكتاب يقول أهدافك غير ثابتة بل مرنة تتغير مع الوقت، واللي ما عاد يناسبك تخلّ عنه، والفشل بعد الخبرات مجرد فرصة لتعديل أو هدف جديد (ص 15).","fix":"عدّل، أضف، أو تخلّ عن الهدف اللي ما عاد يناسبك.","coach":"أي خيار فيه «ثابتة» أو «لازم تكمل مهما صار» غلط.","sec":"GS151-U1"},{"id":"g2.playground-numbering","ar":"الملعب رقم (1) هو المهم العاجل، زي مصفوفة كوفي المشهورة.","explain":"الكتاب يرقّم الملاعب بطريقته: (1) المهم غير العاجل = الأولويات، (2) المهم العاجل = الاحتراق، (3) غير المهم العاجل = الرنين، (4) غير المهم غير العاجل = الهروب (ص 28، 32).","fix":"ملعب (1) = الأخضر = المهم غير العاجل = الأولويات = أولوية (أ).","coach":"احفظها بالأسماء: أولويات ← احتراق ← رنين ← هروب، يعني 1-2-3-4.","sec":"GS151-U2"},{"id":"g2.priority-a-urgent","ar":"أولوية (أ) يعني أهم شي وأعجل شي، يعني المهم العاجل.","explain":"(أ) خاصة بالأعمال المهمة وغير العاجلة (تخطيط إستراتيجي وإدارة المستقبل). المهم العاجل هو (ب) وينسوى بإدارة الأزمات وأسلوب المطافئ (ص 34).","fix":"أ = مهم غير عاجل، ب = مهم عاجل، ج = عاجل غير مهم، د = لا مهم ولا عاجل.","coach":"الحرف الأول = الملعب الأول = الأخضر.","sec":"GS151-U2"},{"id":"g2.facts-under-runs","ar":"حقيقة إن الوقت ما ينخزن ولا ينوقف ولا ينسرع تبع خاصية «الوقت يجري».","explain":"الحقايق الأربع (168 ساعة للكل، ما ينخزن، ما تتلاعب بمسيرته، ما تصرفه إلا بمعدله) جات تحت «الوقت محدود» (ص 20–21). «الوقت يجري» عن إحساسنا بسرعة مضيه لما نحتاج وقت أكثر.","fix":"أي حقيقة عن الكمية الثابتة أو المعدل الثابت = الوقت محدود.","coach":"الجملة عن الكمية والحدود؟ محدود. عن السرعة والإحساس؟ يجري.","sec":"GS151-U2"},{"id":"g2.constraint-vs-resource","ar":"الإدارة الحديثة تشوف الوقت قيد constraint، والقديمة تشوفه مورد.","explain":"العكس: القديمة شافته قيد يقاس به الإنتاج وتحدد به الميزانيات، والحديثة عدّلت النظرة وصارت تشوفه مورد Resource زي المالي والبشري، بس محدود (ص 20).","fix":"قديم = قيد، حديث = مورد.","coach":"قيد وقديم يبدون بالقاف.","sec":"GS151-U2"},{"id":"g2.neglect-goes-to-escape","ar":"إذا أهملت المهم غير العاجل ينزل لملعب الرنين أو الهروب.","explain":"المهم يظل مهم؛ لو أهملته أو أجّلته ينتقل تلقائيًا للملعب (2) المهم العاجل ويصير حريق، وعشان كذا اسمه الاحتراق (ص 31).","fix":"الإهمال ينقل المهمة من (1) إلى (2)، ما ينزّلها لغير المهم.","coach":"تذكّر صيانة السيارة وألم الضرس: التأجيل حوّلها حريق.","sec":"GS151-U2"},{"id":"g2.urgent-means-important","ar":"أي شي عاجل يعني مهم، فلازم أترك كل شي وأرد عليه.","explain":"العاجل عند الكتاب «الفورى الذي لا يحتمل تأجيلاً.. بغض النظر عن أهميته». كثير من العاجل غير مهم = ملعب الرنين، ومهامه غالبًا محبوبة وممتعة وسهلة (ص 31–32).","fix":"اسأل سؤالين منفصلين: هل هو مهم؟ وهل هو عاجل؟","coach":"رنة الجوال مو دليل أهمية.","sec":"GS151-U2"},{"id":"g2.success-vs-happiness","ar":"الناجحون والسعداء نفس الشي: الاثنين معظم وقتهم في ملعب (1) بس.","explain":"الناجحون أكثر وقتهم في ملاعب المهم (1) و(2)، أما السعداء فمعظم وقتهم في ملعب المهم غير العاجل (1) بس (ص 33).","fix":"ناجح = (1) و(2). سعيد = (1).","coach":"السعادة أضيق: ملعب واحد بس.","sec":"GS151-U2"},{"id":"g2.symptom-vs-cure","ar":"الخوف من الفشل أو ترتيب المكان قبل الشغل من طرق علاج التسويف.","explain":"الكتاب يفرّق ثلاث قوايم: أعراض التسويف (5) ومنها الخوف من الفشل، وصفات المسوفين (6) ومنها ترتيب المكان طويلًا قبل العمل الصعب، وطرق العلاج (6) مثل تحديد وقت لكل مهمة والبدء فورًا (ص 35–36).","fix":"العلاج كله أفعال أمر: ضع، خذ، اكتب، شجع، ابدأ، تذكّر.","coach":"الجملة تبدأ بفعل أمر؟ غالبًا علاج.","sec":"GS151-U2"},{"id":"g2.sand-first","ar":"الأفضل أخلص الأشياء الصغيرة والسهلة أول عشان أفضّي بالي للكبيرة.","explain":"في قصة فنجان القهوة لما بدأ الأستاذ بالرمل ما بقى مكان للأحجار الكبيرة، ولما بدأ بالكبيرة دخل كل شي بعدها (ص 36–38).","fix":"ابدأ بالأحجار الكبيرة، والبقية مجرد رمل.","coach":"كبير ← متوسط ← صغير ← رمل ← ماء ← قهوة.","sec":"GS151-U2"},{"id":"g2.coffee-meaning","ar":"فنجان القهوة في القصة يمثل التوافه، أو يمثل أهم شي في الحياة.","explain":"الأستاذ قال إنه أضافه عشان يوضح إن مهما كانت حياتك مليانة يبقى دايم مكان للاسترخاء مع فنجان قهوة (ص 38). التوافه هي الرمل والماء.","fix":"القهوة = مساحة الاسترخاء.","coach":"قهوة = راحة.","sec":"GS151-U2"},{"id":"g2.pyramid-order","ar":"الحاجة إلى التعلم احتياجات النفس، والحب احتياجات العقل.","explain":"هرم الأحجار الكبيرة: الحياة = الجسد (القاعدة)، الحب = النفس، التعلم = العقل، ترك الأثر = الروح (القمة) (ص 38).","fix":"من تحت لفوق: جسد ← نفس ← عقل ← روح.","coach":"تخيل إنك تكبر: تعيش، تحب، تتعلم، تترك أثر.","sec":"GS151-U2"},{"id":"g2.rocks-vs-pebbles","ar":"الوظيفة والمال والبيت من الأحجار الكبيرة.","explain":"الأحجار الكبيرة: دينك، قيمك، أخلاقك، عائلتك، أطفالك، صحتك، أصدقاءك، ولو فقدت كل شي وبقت تظل حياتك مليانة. الوظيفة والبيت والسيارة والمال والهوايات حصى (ص 37).","fix":"اللي لو راح كل شي وبقى تظل حياتك ثابتة = حجر كبير.","coach":"الأصدقاء حجر كبير، والوظيفة حصى.","sec":"GS151-U2"},{"id":"g3.arkan-mix","ar":"يخلط أركان القرار مع أركان صناعة القرار","explain":"الرسم الدائري في ص 43 اسمه أركان صناعة القرار وفيه الصبر والأفضل والمخاطرة، أما تعريف القرار فيطلع منه ثلاثة أركان ثانية.","fix":"أركان القرار = الاختيار الواعي، البدائل المتاحة، الأهداف المرجوة. أركان صناعة القرار = الصبر، الأفضل، المخاطرة.","coach":"اسأل نفسك: السؤال جاي من التعريف ولا من الرسم الدائري؟ التعريف = اختيار وبدائل وأهداف.","sec":"GS151-U3"},{"id":"g3.economic-vs-admin","ar":"يخلط الرجل الاقتصادي بالرجل الإداري","explain":"الاقتصادي هو الأسلوب العلمي ويدور المثالية والأمثل، والإداري هو القرار المُرضي ويدور الأنسب اللي يكفي.","fix":"Economic Man = العلمي = النموذج الراشد = المثالية. Administrative Man = المُرضي = What Satisfies is good enough = الرضا والواقعية.","coach":"الإداري يرضى بالموجود، والاقتصادي يبي الأفضل دايم.","sec":"GS151-U3"},{"id":"g3.theorist-swap","ar":"ينسب الأساليب للأشخاص الغلط","explain":"كل أسلوب له صاحب في الكتاب، والأسئلة تجي كثير على النسبة.","fix":"ليندبلوم = المحافظ، إتزيوني = التوفيقي (المختلط)، سيد عليوة سمّى العلمي النموذج الراشد، كبنر–تريجو = أسئلة تحديد المشكلة، أوسبورن = العصف الذهني.","coach":"ليندبلوم يرجع لورا (محافظ)، وإتزيوني يوفق بين الاثنين.","sec":"GS151-U3"},{"id":"g3.basic-secondary","ar":"يعكس القرارات الأساسية والثانوية عند إتزيوني","explain":"الأساسية مهمة وبعيدة الأثر وعقلانية بدون تفاصيل، والثانوية أقل أهمية وقصيرة الأثر وتراكمية وتركز على التفاصيل.","fix":"أساسية = long range + عقلاني. ثانوية = short range + تراكمي + تفاصيل.","coach":"تذكر الكاميرتين: الصورة الكلية أساسية، والقطاع الصغير بتفاصيله ثانوية.","sec":"GS151-U3"},{"id":"g3.programmed-flip","ar":"يعكس صفات القرارات المبرمجة وغير المبرمجة","explain":"المبرمجة روتينية ومتكررة ومخاطرتها منخفضة، وغير المبرمجة غير متكررة وعدم التأكد فيها عالي ومخاطرتها مرتفعة.","fix":"المبرمجة: بدائل قليلة ونمطية، أداتها العادة، مثل شراء الملابس. غير المبرمجة: بدائل كثيرة، أداتها التفكير الابتكاري، مثل الزواج واختيار التخصص.","coach":"مبرمجة = برنامج يومي متكرر. قرار تسويه مرة بالعمر = غير مبرمج.","sec":"GS151-U3"},{"id":"g3.stage-order","ar":"يلخبط ترتيب الخطوات التسع ومراحلها","explain":"كل مرحلة فيها ثلاث خطوات بترتيب ثابت، والأسئلة تجي على رقم الخطوة أو مرحلتها.","fix":"المرحلة ١: المواجهة، المعلومات، الصياغة. المرحلة ٢: إنتاج الأفكار، تقييم البدائل، الاختيار. المرحلة ٣: التنفيذ، المتابعة والتقييم، المرونة.","coach":"حدد المشكلة، بعدين قرر، بعدين نفذ: ٣ × ٣.","sec":"GS151-U3"},{"id":"g3.decision-terms","ar":"يعتبر اتخاذ القرار وصناعته وإصداره نفس الشي","explain":"الكتاب يفرق: صناعة القرار هي العملية كلها، اتخاذ القرار هو خطوة الاختيار (أو خطوات المرحلة الثانية)، وإصدار القرار هو المرحلة الثالثة.","fix":"حل المشكلات = ٦ خطوات، وصناعة القرار = ٩ خطوات كاملة.","coach":"الصناعة = المصنع كله، الاتخاذ = لحظة الاختيار، الإصدار = طلعة القرار للتنفيذ.","sec":"GS151-U3"},{"id":"g3.symptom-vs-problem","ar":"يحسب العرض أو المشكلة الفرعية هي المشكلة الحقيقية","explain":"المشكلة الفرعية عرض مؤقت ينتج من الحقيقية ويختفي باختفائها، والانشغال بالأعراض يبقيك في المشكلة بلا حل.","fix":"المشكلة الحقيقية = العقبة الرئيسية اللي ما يتحقق الهدف إلا بحلها. ركز جهدك عليها مو على أعراضها.","coach":"الحرارة عرض، والالتهاب هو المشكلة: عالج السبب.","sec":"GS151-U3"},{"id":"g3.data-types","ar":"يخلط البيانات الأولية والثانوية والتاريخية والتنبؤات","explain":"كل نوع له مصدر مختلف: الأولية تنجمع للموضوع نفسه، الثانوية جمعت لغرض ثاني، التاريخية من الماضي، والتنبؤات حدس وتخمين.","fix":"الاستبانة لموضوعك = أولية. إحصائية لغرض ثاني تصلح لك = ثانوية. خبرات وفترات وأفراد سابقين = تاريخية.","coach":"اسأل: انجمعت عشان موضوعي ولا لغرض ثاني ولا من زمان؟","sec":"GS151-U3"},{"id":"g3.tool-mix","ar":"يخلط أدوات تحليل وعرض المعلومات ببعض","explain":"كل أداة لها وظيفة: باي للجزء والكل، المدرج لتوزيع خاصية بالأعمدة، الزمن لتغير حدث عبر الوقت، التدفق للمدخلات ونقاط القرار، بيرت للوقت والتكلفة، وإيشيكاوا للسبب والنتيجة.","fix":"طابق الوظيفة بالأداة: جزء من كل = باي، أسباب مشكلة = إيشيكاوا، أنشطة ووقت وتكلفة = بيرت.","coach":"باي = فطيرة مقسومة، إيشيكاوا = سمكة أسباب، بيرت = جدول مشروع.","sec":"GS151-U3"},{"id":"g3.effectiveness-quality","ar":"يظن الجودة لحالها تحدد فاعلية القرار أو يجمع بدل ما يضرب","explain":"الكتاب يقول فاعلية القرار = النوعية × مدى القبول، فالقرار الأقل جودة ممكن يكون أفعل لو قبوله أعلى.","fix":"٨×٢ = ١٦ أقل من ٦×٤ = ٢٤. الحل الوسط المقبول غالبًا أفعل من الحل الصحيح المرفوض.","coach":"قرار ممتاز محد يقبله = صفر تقريبًا. اضرب، لا تجمع.","sec":"GS151-U3"},{"id":"g3.brainstorm-judge","ar":"يظن نقيّم الأفكار أول بأول في العصف الذهني","explain":"العصف الذهني قايم على طرح الأفكار عفوية، والإرشادات تمنع الحكم على أي فكرة قبل اكتمال الطرح، لأن الفكرة الغريبة ممكن تكون نواة لفكرة جيدة.","fix":"الطرح أول بدون حكم أو تعليق، والمسجل يسجل كل شي، والتقييم يجي في الخطوة الخامسة.","coach":"في الجلسة: اكتب، لا تحكم.","sec":"GS151-U3"}],"cases":[],"questions":[{"n":101,"lo":"U1","sec":"GS151-U1","type":"term","topic":"تعريف الهدف","stem":"«الأمر المهم بالنسبة لك والذي تسعى لتحقيق انجاز فيه» هذا تعريف:","options":["الغاية","الأمنية","الهدف","الحلم"],"answer":2,"why":"هذا تعريف الهدف بالحرف في ص 8، والكلمة المفتاحية «تسعى لتحقيق انجاز»؛ يعني فيه سعي وتخطيط، مو بس رغبة.","wrong":[{"i":0,"mis":"g1.ghaya-level","note":"الغاية أعلى درجات الأهداف وأكثرها طموح (ص 9)، مو التعريف العام للهدف"},{"i":1,"mis":"g1.umniya-vs-hulm","note":"الأمنية رغبة بدون برنامج عملي، والتعريف هنا فيه سعي للإنجاز"},{"i":3,"mis":"g1.umniya-vs-hulm","note":"الحلم صاحبه يستبعد إنه يصير، فما فيه سعي"}],"tests":["تعريف الهدف","الفرق بين الهدف ومرادفاته"]},{"n":102,"lo":"U1","sec":"GS151-U1","type":"list","topic":"عناصر الهدف","stem":"عناصر الهدف الثلاثة كما وردت في الكتاب هي:","options":["تحديد الغاية – تحديد الوسيلة – تحديد المعيار","أمر مهم – خاص بك – تخطط لتنفيذه","محدد – قابل للقياس – واقعي","أمر مهم – تتمناه – تحلم بتحقيقه"],"answer":1,"why":"ص 8 تقول «فهذه ثلاثة عناصر للهدف»: أمر مهم، خاص بك، تخطط لتنفيذه. وهي نفسها الدوائر الثلاث حول كلمة «الهدف» بالشكل.","wrong":[{"i":0,"mis":"g1.elements-vs-pillars","note":"هذي أركان التخطيط الثلاثة، مو عناصر الهدف"},{"i":2,"mis":"gen.neighbor","note":"هذي من صفات SMART (ص 12)، مو عناصر الهدف"},{"i":3,"mis":"g1.umniya-vs-hulm","note":"التمني والحلم مرادفات للهدف، والهدف لازم تخطط لتنفيذه"}],"tests":["عناصر الهدف الثلاثة"]},{"n":103,"lo":"U1","sec":"GS151-U1","type":"list","topic":"أركان التخطيط","stem":"تحديد الهدف هو أول ركن من أركان التخطيط الثلاثة: (تحديد الغاية – تحديد الوسيلة – ..........)","options":["تحديد الأولويات","تحديد الوقت","تحديد المعيار","تحديد المعوقات"],"answer":2,"why":"أركان التخطيط في ص 8 بالترتيب: تحديد الغاية، تحديد الوسيلة، تحديد المعيار. وتحديد الهدف هو الركن الأول.","wrong":[{"i":0,"mis":"gen.neighbor","note":"ترتيب الأولويات ضابط من ضوابط الهدف (ص 13)، مو ركن تخطيط"},{"i":1,"mis":"gen.neighbor","note":"الوقت صفة في SMART (مرتبط بوقت)، مو من الأركان"},{"i":3,"mis":"gen.neighbor","note":"مراقبة المعوقات ضابط رقم 10 (ص 14)، مو ركن"}],"tests":["أركان التخطيط الثلاثة","تحديد الهدف أول ركن"]},{"n":104,"lo":"U1","sec":"GS151-U1","type":"scenario","topic":"الأمنية","stem":"سعد يقول من سنين: «ودي أتعلم الإنجليزي»، وهو مقتنع إنه يقدر، لكنه ما سجّل في أي دورة ولا وضع له أي خطة. حسب الكتاب، الشيء اللي عند سعد يسمى:","options":["هدف","غاية","حلم","أمنية"],"answer":3,"why":"الأمنية في ص 9 = أمر تبي تحققه بس ما تحط له برنامج عملي. سعد يبيه ومقتنع إنه ممكن، بس ما خطط له، فهي أمنية.","wrong":[{"i":0,"mis":"gen.partial","note":"الهدف لازم تخطط لتنفيذه (ص 8)، وسعد ما حط أي برنامج"},{"i":1,"mis":"g1.ghaya-level","note":"الغاية أعلى درجات الأهداف وأكثرها طموح، مو رغبة بلا خطة"},{"i":2,"mis":"g1.umniya-vs-hulm","note":"الحلم صاحبه يستبعد إنه يصير، وسعد شايفه ممكن"}],"tests":["تعريف الأمنية","الفرق بين الأمنية والحلم"]},{"n":105,"lo":"U1","sec":"GS151-U1","type":"tf","topic":"الغاية","stem":"حسب الكتاب، الغاية هي أعلى درجات الأهداف، وأكثرها طموحاً.","options":["صح","خطأ"],"answer":0,"why":"صح، هذا تعريف الغاية بالحرف في ص 9 تحت «مرادفات الهدف».","wrong":[{"i":1,"mis":"g1.ghaya-level","note":"الغاية مو هدف عادي ولا أقل منه؛ هي أعلى درجة"}],"tests":["تعريف الغاية"]},{"n":106,"lo":"U1","sec":"GS151-U1","type":"list","topic":"لماذا نضع الأهداف","stem":"كل التالي من أسباب وضع الأهداف كما وردت في الكتاب، ما عدا:","options":["تعطيك القدرة على التركز في جمع المعلومات واكتساب المعرفة","تعطيك القدرة على تنظيم وقتك وحصر مواردك وقدراتك","تعطيك الرؤيا المستقبلية على المدى القصير، والحافز للإنجاز على المدى الطويل","ترفع قدر ثقتك بنفسك واعتزازك بقدراتك"],"answer":2,"why":"في ص 9 السبب الأول جاي مقلوب هنا: الكتاب يقول الأهداف تعطيك الرؤيا على المدى الطويل، والحافز للإنجاز على المدى القصير. الباقي كلها أسباب صحيحة.","wrong":[{"i":0,"mis":"gen.detail","note":"هذا السبب رقم 2 (الوعاء المعرفي)، يعني صحيح وما ينفع يكون المستثنى"},{"i":1,"mis":"gen.detail","note":"هذا السبب رقم 3، صحيح"},{"i":3,"mis":"gen.detail","note":"هذا السبب رقم 5، صحيح"}],"tests":["أسباب وضع الأهداف (5)","الرؤيا للمدى الطويل والحافز للقصير"]},{"n":107,"lo":"U1","sec":"GS151-U1","type":"scenario","topic":"أنواع الأهداف","stem":"طالب وضع هدفاً: «أن أتخرج من بكالوريوس إدارة الأعمال خلال 4 سنوات». حسب تقسيم الكتاب للأهداف من حيث الزمن، هذا الهدف:","options":["طويل المدى","متوسط المدى","قصير المدى","إجرائي"],"answer":1,"why":"ص 9: المتوسطة المدى هي المرتبطة بمرحلة معينة «كمرحلة الجامعة»، ومدتها بين 3 أو 5 و10 سنوات. وهدف التخرج 4 سنوات ومرحلة جامعة.","wrong":[{"i":0,"mis":"g1.long-term-span","note":"الطويل يزيد عن 10 سنوات، ويسمونه أهداف العمر"},{"i":2,"mis":"g1.short-vs-near","note":"القصير أقل من 3 سنوات، و4 سنوات أكثر"},{"i":3,"mis":"g1.operational-todo","note":"الإجرائي أنشطة شهرية أو أسبوعية أو يومية"}],"tests":["أنواع الأهداف من حيث الزمن","الأهداف متوسطة المدى"]},{"n":108,"lo":"U1","sec":"GS151-U1","type":"tf","topic":"الأهداف الإجرائية","stem":"حسب الكتاب، الأهداف قصيرة المدى هي الأهداف اللي نكتبها في قوائم المهام (To Do list) كأنشطة يومية وأسبوعية.","options":["صح","خطأ"],"answer":1,"why":"خطأ. قوائم المهام (To Do list) للأهداف الإجرائية أو التشغيلية (ص 9). أما القصيرة فهي اللي يقل زمن تنفيذها عن 3 سنوات.","wrong":[{"i":0,"mis":"g1.operational-todo","note":"خلطت القصيرة بالإجرائية؛ قوائم المهام للإجرائية أو التشغيلية"}],"tests":["الأهداف الإجرائية أو التشغيلية","قوائم المهام","الأهداف قصيرة المدى"]},{"n":109,"lo":"U1","sec":"GS151-U1","type":"scenario","topic":"أدوار الحياة","stem":"«هل هناك مشاكل تعيدك للخلف، وتعوقك عن التقدم؟» هذا السؤال تسأله لنفسك عند وضع أهداف الدور:","options":["الصحي","المهني","الترفيهي","النفسي"],"answer":3,"why":"في الخطوة الثانية (ص 11) الدور النفسي سؤاله عن المشاكل اللي ترجعك للخلف، والمطلوب تحط أهداف تحسّن سلوكك وتحل المشكلات المعلقة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الصحي سؤاله عن الأهداف الرياضية والصحة مع تقدم العمر"},{"i":1,"mis":"gen.neighbor","note":"المهني سؤاله عن المستوى اللي تبي توصل له في مهنتك"},{"i":2,"mis":"gen.neighbor","note":"الترفيهي سؤاله عن أفضل أسلوب تستمتع فيه بالحياة"}],"tests":["أدوار الحياة التسعة","الخطوة الثانية: أهداف لكل مجال"]},{"n":110,"lo":"U1","sec":"GS151-U1","type":"concept","topic":"الأهداف قريبة المدى","stem":"في خطوات وضع الأهداف، «الأهداف قريبة المدى» (الخطوة الرابعة) هي مجموعة أهداف لـ:","options":["الخمس سنوات القادمة","السنة القادمة","العشر سنوات القادمة","الشهر القادم"],"answer":0,"why":"ص 11: الأهداف قريبة المدى «لخمس سنوات القادمة»، ومأخوذة من أهداف العمر. السنة والشهر من الأهداف التنفيذية في الخطوة الخامسة.","wrong":[{"i":1,"mis":"g1.short-vs-near","note":"السنة من الأهداف التنفيذية (الخطوة الخامسة)"},{"i":2,"mis":"g1.long-term-span","note":"العشر سنوات وأكثر للأهداف البعيدة"},{"i":3,"mis":"gen.neighbor","note":"الشهر من الأهداف التنفيذية"}],"tests":["الأهداف قريبة المدى = 5 سنوات","خطوات وضع الأهداف الست"]},{"n":111,"lo":"U1","sec":"GS151-U1","type":"tf","topic":"المسؤولية عن الهدف","stem":"في خطوة العصف الذهني، يطلب منك الكتاب أن تتأكد إن أهدافك ممكن يتحمل مسؤولية تحقيقها أحد الوالدين أو الأصدقاء بدلاً عنك.","options":["صح","خطأ"],"answer":1,"why":"خطأ. ص 11 تقول تأكد إنك أنت المسؤول عن تحقيقها، مو غيرك ممن تقدر تفوضهم مثل الوالدين أو الأبناء أو الموظفين أو الأصدقاء. وضابط رقم 8 (ص 14): لا تخلي أحد يحط لك أهدافك.","wrong":[{"i":0,"mis":"g1.own-goals","note":"المسؤول عن أهدافك أنت، مو أحد تفوضه"}],"tests":["الخطوة الثالثة: العصف الذهني","المسؤولية الشخصية عن الأهداف"]},{"n":112,"lo":"U1","sec":"GS151-U1","type":"term","topic":"صاحب SMART","stem":"جمع سمات الهدف الفعال في كلمة واحدة هي SMART:","options":["الدكتور جورج دوران","أدوين بلس","ستيفن كوفي","بيتر دراكر"],"answer":0,"why":"ص 12: الكتاب يقول الدكتور جورج دوران جمعها في كلمة وحدة هي SMART. أدوين بلس صاحب أبجدية الأولويات (ص 13).","wrong":[{"i":1,"mis":"g1.abc-priority","note":"أدوين بلس صاحب فكرة أبجدية الأولويات، مو SMART"},{"i":2,"mis":"gen.detail","note":"اسم ما جا في الوحدة أصلاً"},{"i":3,"mis":"gen.detail","note":"اسم ما جا في الوحدة أصلاً"}],"tests":["SMART وصاحبها"]},{"n":113,"lo":"U1","sec":"GS151-U1","type":"figure","topic":"شكل SMART","stem":"في شكل SMART بالكتاب، حرف A يرمز إلى:","img":"img/gs151/U1-p012.png","options":["Achievable – طموح","Attainable – يمكن تحقيقه","Accurate – دقيق","Actual – واقعي"],"answer":1,"why":"في الشكل ص 12: A = Attainable = يمكن تحقيقه. والواقعي حرف R (Realistic).","wrong":[{"i":0,"mis":"gen.detail","note":"الكتاب كاتبها Attainable، والطموح وصف الغاية مو حرف A"},{"i":2,"mis":"gen.detail","note":"دقيق مو من حروف SMART بالكتاب"},{"i":3,"mis":"g1.attainable-vs-realistic","note":"واقعي هو حرف R مو A"}],"tests":["حروف SMART بالإنجليزي والعربي"]},{"n":114,"lo":"U1","sec":"GS151-U1","type":"concept","topic":"الأسئلة الخمسة 5Ws","stem":"عشان يكون هدفك محدداً (Specific)، لازم تجاوب بتحديد شديد على الأسئلة الخمسة (5Ws)، وهي:","options":["What, Why, How, How much, When","Who, What, Where, When, How","Who, Why, Where, Which, When","Who, What, Where, When, Why"],"answer":3,"why":"ص 12: الـ5Ws هي Who, What, Where, When, Why (من، ماذا، أين، متى، لماذا). كلها تبدأ بـ W، وما فيها How.","wrong":[{"i":0,"mis":"g1.specific-vs-measurable","note":"How much سؤال كمية وقياس، مو من الـ5Ws"},{"i":1,"mis":"gen.partial","note":"How مو منها، الخامس Why"},{"i":2,"mis":"gen.detail","note":"Which مو منها، الصح What"}],"tests":["سمة المحدد Specific","الأسئلة الخمسة 5Ws"]},{"n":115,"lo":"U1","sec":"GS151-U1","type":"scenario","topic":"قابل للقياس","stem":"ريم تبي تتابع تقدمها في القراءة وتقارنه بالوضع المطلوب، فغيّرت هدفها من «أقرأ أكثر» إلى «أقرأ 12 كتاب». السمة اللي حققتها بإضافة الرقم هي:","options":["قابل للقياس Measurable","محدد Specific","واقعي Realistic","مرتبط بوقت Time-bound"],"answer":0,"why":"ص 13: عشان تتابع التقدم لازم يكون الهدف كمي بالأرقام غالباً، وهذا يسهّل قياسه ومقارنته بالوضع المطلوب. يعني قابل للقياس.","wrong":[{"i":1,"mis":"g1.specific-vs-measurable","note":"المحدد يجاوب على الـ5Ws، والأرقام والكمية للقياس"},{"i":2,"mis":"g1.attainable-vs-realistic","note":"الواقعية تخص الهدف نفسه، مو إضافة رقم"},{"i":3,"mis":"gen.neighbor","note":"ما أضافت وقت بداية ولا نهاية، أضافت رقم"}],"tests":["سمة قابل للقياس Measurable"]},{"n":116,"lo":"U1","sec":"GS151-U1","type":"concept","topic":"قابل للتحقيق مقابل واقعي","stem":"حسب الكتاب، الفرق بين «قابل للتحقيق» و«واقعي» في SMART هو أن:","options":["قابلية التحقيق تخص الهدف نفسه، والواقعية تخص صاحب الهدف","ما فيه فرق، الاثنين بنفس المعنى","قابلية التحقيق تخص صاحب الهدف، والواقعية تخص الهدف نفسه","الواقعية تخص الوقت، وقابلية التحقيق تخص الأرقام"],"answer":2,"why":"ص 13 صريحة: قابلية التحقيق خاصة بصاحب الهدف (مهاراته وقدراته والظروف الخارجية)، والواقعية تخص الهدف نفسه.","wrong":[{"i":0,"mis":"gen.reversed","note":"قلبتها: التحقيق لصاحب الهدف، والواقعية للهدف"},{"i":1,"mis":"g1.attainable-vs-realistic","note":"فيه فرق: وحدة تخصك أنت، والثانية تخص الهدف"},{"i":3,"mis":"gen.neighbor","note":"الوقت لحرف T والأرقام لحرف M"}],"tests":["قابل للتحقيق Attainable","واقعي Realistic"]},{"n":117,"lo":"U1","sec":"GS151-U1","type":"tf","topic":"مرتبط بوقت","stem":"حسب الكتاب، الهدف المرتبط بوقت (Time-bound) لازم يكون له وقت للبدء ووقت آخر للانتهاء من تحقيقه.","options":["صح","خطأ"],"answer":0,"why":"صح. ص 13 تقول لازم تحط وقت للبدء وآخر للانتهاء، وهذا يحطك على طريق الإنجاز ويمنع الأهداف الصغيرة اليومية تعطلك.","wrong":[{"i":1,"mis":"gen.partial","note":"مو بس وقت نهاية؛ الكتاب يطلب وقت بداية ووقت نهاية"}],"tests":["سمة مرتبط بوقت Time-bound"]},{"n":118,"lo":"U1","sec":"GS151-U1","type":"list","topic":"ضوابط لهدف أكثر فاعلية","stem":"كل التالي من «ضوابط لهدف أكثر فاعلية»، ما عدا:","options":["ضع الهدف الواحد في جملة واحدة","استعمل صيغة النفي مثل «ألا أفعل كذا» عشان يكون الهدف أوضح","استخدم الورق","ابحث عن رفيق لهدفك"],"answer":1,"why":"ص 13 الضابط الثاني عكسها: لا تستعمل النفي، قل «أن أفعل كذا» ولا تقول «أن لا أفعل كذا». الباقي كلها من الضوابط العشرة.","wrong":[{"i":0,"mis":"gen.detail","note":"هذا الضابط رقم 1، صحيح"},{"i":2,"mis":"gen.detail","note":"هذا الضابط رقم 5 (ص 14)، صحيح"},{"i":3,"mis":"gen.detail","note":"هذا الضابط رقم 9 (ص 14)، صحيح"}],"tests":["ضوابط الهدف العشرة","لا تستعمل النفي"]},{"n":119,"lo":"U1","sec":"GS151-U1","type":"figure","topic":"أبجدية الأولويات","stem":"في جدول «أبجدية الأولويات» بالكتاب، الأهداف 9 و8 و6 موجودة تحت حرف (د). هذا يعني أنها:","img":"img/gs151/U1-p013.png","options":["أكثر الأهداف أولوية","أهداف ما لها وقت محدد","أهداف لازم تُلغى","أقل الأهداف أولوية"],"answer":3,"why":"ص 13: كل هدف ياخذ حرف من (أ – ب – جـ – د)، و(أ) أكثرها أولوية و(د) أقلها. فالأهداف تحت (د) تجي آخر شي.","wrong":[{"i":0,"mis":"g1.abc-priority","note":"قلبتها؛ (أ) الأعلى و(د) الأقل"},{"i":1,"mis":"gen.detail","note":"الحروف للأولوية، ما لها علاقة بالوقت"},{"i":2,"mis":"gen.absolute","note":"الكتاب ما قال تلغيها، بس أولويتها أقل"}],"tests":["أبجدية الأولويات","ترتيب أ ب جـ د"]},{"n":120,"lo":"U1","sec":"GS151-U1","type":"concept","topic":"ابحث عن مرشد","stem":"عند تحويل الأهداف إلى أنشطة، قال الكتاب عن خطوة «ابحث عن مرشد»:","options":["خله يحقق أهدافك بدلاً عنك","اتخذه قدوة، ولكن دون أن تقلد","قلّده بالحرف عشان توصل أسرع","ما تحتاج مرشد إذا عندك معلومات"],"answer":1,"why":"ص 15: محد يقدر يحقق أهدافك عنك، بس ادرس الخبرات ودوّر إجابات لأسئلتك، واتخذ قدوة لكن بدون تقليد.","wrong":[{"i":0,"mis":"g1.own-goals","note":"الكتاب قال ما أحد يقدر يحقق أهدافك عنك"},{"i":2,"mis":"gen.reversed","note":"الكتاب قال اتخذ قدوة بس دون أن تقلد"},{"i":3,"mis":"gen.neighbor","note":"المعلومات خطوة مستقلة (رقم 5)، ما تلغي المرشد"}],"tests":["تحويل الأهداف إلى أنشطة","ابحث عن مرشد"]},{"n":121,"lo":"U1","sec":"GS151-U1","type":"concept","topic":"على طريق التنفيذ","stem":"حسب الكتاب، إذا كان تحقيق الهدف الأول سهلاً، فالمفروض:","options":["تخلي الهدف التالي أصعب","تخلي الهدف التالي أسهل","توقف وضع أهداف جديدة لين تخلص خطتك","تعيد نفس الهدف مرة ثانية"],"answer":0,"why":"ص 15 (النقطة 4): لو الهدف الأول كان سهل خل التالي أصعب، ولو أخذ وقت طويل خل التالي أسهل.","wrong":[{"i":1,"mis":"gen.reversed","note":"هذا لو الهدف الأول أخذ وقت طويل في التنفيذ"},{"i":2,"mis":"g1.goals-flexible","note":"الكتاب يقول راجع خططك وعدّلها، مو توقف"},{"i":3,"mis":"gen.detail","note":"ما جا بالكتاب"}],"tests":["على طريق التنفيذ (8 نقاط)","مراجعة الخطط بعد الإنجاز"]},{"n":122,"lo":"U1","sec":"GS151-U1","type":"figure","topic":"مثال هاني","stem":"في مثال هاني موظف البنك، هدف العشر سنوات كان:","img":"img/gs151/U1-p016.png","options":["أن يكون مديراً لأحد فروع البنك في وطنه","أن يكون رئيساً لأحد أقسام الفرع","أن يكون نائب مدير فرع البنك","العودة إلى الدراسات العليا لإنهاء الماجستير"],"answer":2,"why":"ص 16: هدف العمر = مدير فرع، هدف العشر سنوات = نائب مدير الفرع، هدف الخمس سنوات = رئيس قسم، وهدف الست شهور = الماجستير.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا هدف العمر (الطويل)، مو هدف العشر سنوات"},{"i":1,"mis":"gen.neighbor","note":"هذا هدف الخمس سنوات"},{"i":3,"mis":"gen.neighbor","note":"هذا هدف الستة أشهر"}],"tests":["مثال هاني","تجزئة هدف العمر"]},{"n":201,"lo":"U2","sec":"GS151-U2","type":"term","topic":"تعريف إدارة الوقت","stem":"«الأستخدام الأفضل للوقت بالإمكانيات المتاحة بطريقة تؤدي الى تحقيق الأهداف» — هذا تعريف الكتاب لـ:","options":["الوقت","مصفوفة الوقت","إدارة الوقت","استثمار الوقت"],"answer":2,"why":"ص 20: الكتاب يحط تعريفين في مربع واحد: الوقت «مقدار من الزمن قدر لأمر ما»، وإدارة الوقت هي الاستخدام الأفضل للوقت بالإمكانيات المتاحة عشان توصل لأهدافك. كلمة «تحقيق الأهداف» هي مفتاح إدارة الوقت.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الوقت نفسه تعريفه «مقدار من الزمن قدر لأمر ما»، مو الاستخدام الأفضل"},{"i":1,"mis":"gen.keyword","note":"المصفوفة أداة تقسّم المهام حسب الأهمية والعجلة، مو هذا التعريف"},{"i":3,"mis":"gen.neighbor","note":"استثمار الوقت عن تضاعف الإنتاجية داخل الوقت الواحد (ص 22)"}],"tests":["تعريف إدارة الوقت"]},{"n":202,"lo":"U2","sec":"GS151-U2","type":"tf","topic":"تعريف الوقت","stem":"الكتاب يعرّف «الوقت» بأنه الاستخدام الأفضل للإمكانيات المتاحة بطريقة توصل لتحقيق الأهداف.","options":["صح","خطأ"],"answer":1,"why":"ص 20: هذا تعريف «إدارة الوقت» مو الوقت. الوقت عند الكتاب «مقدار من الزمن قدر لأمر ما».","wrong":[{"i":0,"mis":"gen.neighbor","note":"خلطت بين تعريف الوقت وتعريف إدارة الوقت، الاثنين في نفس المربع"}],"tests":["تعريف الوقت","تعريف إدارة الوقت"]},{"n":203,"lo":"U2","sec":"GS151-U2","type":"concept","topic":"الوقت: قيد أو مورد","stem":"نظريات الإدارة القديمة كانت تشوف الوقت «قيد constraint يقاس به الإنتاج». كيف عدّلت نظريات الإدارة الحديثة هالنظرة؟","options":["صارت تشوفه أمر يخص إدارة الأعمال بس","صارت تشوفه مورد Resource مثل الموارد المالية والبشرية","صارت تشوفه مورد غير محدود نقدر نخزن منه","صارت تشوفه قيد تتحدد به الميزانيات فقط"],"answer":1,"why":"ص 20: الإدارة الحديثة صارت تشوف الوقت «Resource أي مورد من الموارد مثل الموارد المالية والموارد البشرية»، بس للأسف مورد محدود لأن أعمارنا لها بداية ونهاية.","wrong":[{"i":0,"mis":"gen.detail","note":"هذا ظن كثير من الناس في مقدمة الوحدة، والكتاب يرد عليه"},{"i":2,"mis":"gen.absolute","note":"الكتاب يقول مورد محدود، ومستحيل تخزن منه شي"},{"i":3,"mis":"g2.constraint-vs-resource","note":"القيد هو النظرة القديمة، مو الحديثة"}],"tests":["الوقت قيد أم مورد","الوقت محدود"]},{"n":204,"lo":"U2","sec":"GS151-U2","type":"list","topic":"طبيعة الوقت","stem":"طبيعة الوقت في الكتاب ست خصائص. كل التالي منها ما عدا:","options":["الوقت غالٍ","نمو الوقت","تخزين الوقت","تعويض الوقت"],"answer":2,"why":"ص 20: الست هي: الوقت غالٍ، الوقت محدود، تعويض الوقت، الوقت يجري، نمو الوقت، استثمار الوقت. التخزين مو منها، بالعكس الكتاب يقول مستحيل تخزّن جزء من الوقت (ص 21).","wrong":[{"i":0,"mis":"gen.partial","note":"غالٍ هي الخاصية الأولى، بل أغلى ما يملكه الإنسان"},{"i":1,"mis":"gen.partial","note":"نمو الوقت الخامسة: محدود بس نزيد قيمته بالاستثمار"},{"i":3,"mis":"gen.partial","note":"تعويض الوقت الثالثة، وفكرتها إن اللي يروح ما يرجع مثله"}],"tests":["طبيعة الوقت (6)"]},{"n":205,"lo":"U2","sec":"GS151-U2","type":"concept","topic":"الوقت محدود","stem":"«أنك لا تستطيع التلاعب في مسيرة الوقت بأن توقفه مثلاً أو تسرعه أو تبطئه» — هالحقيقة يذكرها الكتاب تحت أي خاصية من طبيعة الوقت؟","options":["الوقت محدود","الوقت يجري","نمو الوقت","الوقت غالٍ"],"answer":0,"why":"ص 20–21: تحت «٢- الوقت محدود» الكتاب يقول لازم ندرك أربع حقايق: كلنا نملك نفس الكمية (24×7=168 ساعة بالأسبوع)، ومستحيل تخزن منه لوقت لاحق، وما تقدر توقفه أو تسرعه أو تبطئه، وما تصرفه إلا بمعدله (60 ثانية بالدقيقة و60 دقيقة بالساعة). الحقايق الأربع كلها جاية قبل «٣- تعويض الوقت»، يعني تابعة للمحدود مو ليجري (رقم ٤).","wrong":[{"i":1,"mis":"g2.facts-under-runs","note":"«الوقت يجري» (رقم ٤) عن إنه يمضي بسرعة لما نحتاجه، والحقايق الأربع مكتوبة قبله تحت «محدود»"},{"i":2,"mis":"gen.neighbor","note":"نمو الوقت عن زيادة قيمته بالاستثمار"},{"i":3,"mis":"gen.neighbor","note":"غالٍ عن قيمته كنعمة تستاهل الشكر"}],"tests":["الوقت محدود","حقائق الوقت الأربع"]},{"n":206,"lo":"U2","sec":"GS151-U2","type":"tf","topic":"تعويض الوقت","stem":"يستشهد الكتاب بحديث «اغتنم خمسًا قبل خمس» تحت خاصية «تعويض الوقت»، لأن أوقات الصحة والشباب والغنى والفراغ إذا راحت ممكن ما ترجع مثلها.","options":["صح","خطأ"],"answer":0,"why":"ص 21: تحت «تعويض الوقت» سأل الكتاب: هل يمكن تعويض الوقت؟ وجاوب ببيت «ألا ليت الشباب يعود يومًا» وبحديث اغتنم خمسًا: شبابك قبل هرمك، وصحتك قبل سقمك، وغناك قبل فقرك، وفراغك قبل شغلك، وحياتك قبل موتك.","wrong":[{"i":1,"mis":"gen.neighbor","note":"الحديث فعلًا تحت تعويض الوقت، مو تحت الوقت يجري أو المحدود"}],"tests":["تعويض الوقت","اغتنم خمسًا قبل خمس"]},{"n":207,"lo":"U2","sec":"GS151-U2","type":"term","topic":"المسارعة والمسابقة","stem":"حسب الكتاب، «الاستغلال الأمثل للوقت والتنفيذ أول الوقت وعدم التأجيل» هو معنى:","options":["نمو الوقت","إدارة الوقت","استثمار الوقت","المسارعة والمسابقة"],"answer":3,"why":"ص 25: بعد آيتي «وسارعوا» و«سابقوا» يقول الكتاب إن المسارعة والمسابقة هي الاستغلال الأمثل للوقت والتنفيذ أول الوقت وعدم التأجيل.","wrong":[{"i":0,"mis":"gen.neighbor","note":"نمو الوقت: محدود بس نزيد قيمته بالاستثمار (ص 22)"},{"i":1,"mis":"gen.neighbor","note":"إدارة الوقت تعريفها الاستخدام الأفضل بالإمكانيات المتاحة (ص 20)"},{"i":2,"mis":"gen.neighbor","note":"استثمار الوقت عن تضاعف الإنتاجية داخل الوقت الواحد (ص 22)"}],"tests":["المسارعة والمسابقة"]},{"n":208,"lo":"U2","sec":"GS151-U2","type":"tf","topic":"أصل مصفوفة الوقت","stem":"في حوار أيزنهاور مع معاونيه: العلاقة بين الأنشطة المهمة والأنشطة العاجلة طردية، فكل ما زادت أهمية الشي زاد الاستعجال عليه.","options":["صح","خطأ"],"answer":1,"why":"ص 28: الكتاب يقول العلاقة «معكوسة»: «كلما زادت أهمية شيء ما قل الاستعجال عليه والعكس». ومن هالحوار طلعت منظومة الوقت Time Management Matrix.","wrong":[{"i":0,"mis":"gen.reversed","note":"قلبت العلاقة، هي عكسية مو طردية"}],"tests":["مصفوفة الوقت","العلاقة بين المهم والعاجل"]},{"n":209,"lo":"U2","sec":"GS151-U2","type":"scenario","topic":"أين ملعبك؟ مثال السيارة","stem":"اشتريت سيارة جديدة، ولما قربت صيانة الـ5000 كم قلت: «السيارة ماشية وما صار شي» وأجّلت لين تعدّيت 6000 كم. حسب الكتاب، صيانة السيارة الحين صارت في ملعب:","options":["المهم غير العاجل (الأولويات)","غير المهم العاجل (الرنين)","المهم العاجل (الاحتراق)","غير المهم غير العاجل (الهروب)"],"answer":2,"why":"ص 29: لو حجزت موعد قبلها كنت تلعب في ملعب المهم غير العاجل. بس لما أجّلت، السهم في الشكل ينقلها من الأخضر للأحمر: المهم العاجل، وص 31 يسميه ملعب الاحتراق.","wrong":[{"i":0,"mis":"gen.detail","note":"هذا مكانها قبل التأجيل، لو حجزت بدري"},{"i":1,"mis":"g2.urgent-means-important","note":"الصيانة مهمة، فما تنزل لملعب غير المهم"},{"i":3,"mis":"g2.neglect-goes-to-escape","note":"إهمال المهم ينقله للاحتراق مو للهروب"}],"tests":["ملاعب الوقت","التحول من الأولويات للاحتراق"]},{"n":210,"lo":"U2","sec":"GS151-U2","type":"tf","topic":"ملعب الاحتراق","stem":"حسب الكتاب، المهمات اللي مكانها الملعب رقم (1) لما تهمل لعبها فيه، تنتقل تلقائيًا للملعب رقم (2) وتتحول لحريق يحتاج إطفاء عاجل.","options":["صح","خطأ"],"answer":0,"why":"ص 31: بالنص تنتقل «تلقائيًا إلى الملعب رقم (2) (ملعب المهم العاجل)، وتتحول إلى حريق»، وعشان كذا سماه ملعب الاحتراق. والسبب: التسويف (التأجيل) والتجاهل (الإهمال).","wrong":[{"i":1,"mis":"g2.neglect-goes-to-escape","note":"المهم إذا أهملته يصير مهم عاجل، ما ينزل للرنين أو الهروب"}],"tests":["ملعب الاحتراق","التسويف والإهمال"]},{"n":211,"lo":"U2","sec":"GS151-U2","type":"term","topic":"تعريف العاجل","stem":"«الفورى الذي لا يحتمل تأجيلاً.. بغض النظر عن أهميته» — هذا تعريف الكتاب لـ:","options":["العاجل","المهم","الاحتراق","التسويف"],"answer":0,"why":"ص 31: في فقرة الرنين يعرّف الكتاب العاجل بأنه الفوري اللي ما يتحمل تأجيل بغض النظر عن أهميته. أما المهم فعلاماته: المؤثر في حياتنا، وتركه يضيّع مكاسب كثيرة، وزمنه ممتد له أول وآخر.","wrong":[{"i":1,"mis":"g2.urgent-means-important","note":"المهم زمنه ممتد له أول وآخر، مو فوري"},{"i":2,"mis":"gen.neighbor","note":"الاحتراق اسم ملعب المهم العاجل، مو تعريف العاجل"},{"i":3,"mis":"gen.keyword","note":"التسويف تأجيل، يعني عكس اللي ما يتحمل تأجيل"}],"tests":["تعريف العاجل","علامات المهم"]},{"n":212,"lo":"U2","sec":"GS151-U2","type":"scenario","topic":"ملعب الرنين","stem":"كنت مرتب وقتك للمذاكرة، ورن جوالك: صديق يبيك تطلع معه الحين، فطلعت بس لأنه طلبك الحين، بدون ما يكون مرتب له. حسب أمثلة الكتاب، هالنشاط في ملعب:","options":["الرنين","الهروب","الأولويات","الاحتراق"],"answer":0,"why":"ص 32: «الخروج مع صديق في حاجة إليك لمجرد أنه طلبك الآن» من أمثلة الرنين السبعة، مع الكلام في التليفون والجلوس أمام البريد والزيارات غير المرتبة. الرنين يجي كرد فعل مو فعل مرتب له.","wrong":[{"i":1,"mis":"gen.neighbor","note":"الهروب تلجأ له بنفسك من الضغط، هنا أنت ترد على طلب جاك فجأة"},{"i":2,"mis":"g2.urgent-means-important","note":"مو مرتب له ولا هو من أهدافك، فما هو أولوية"},{"i":3,"mis":"g2.urgent-means-important","note":"عاجل بس مو مهم، فما يكون احتراق"}],"tests":["ملعب الرنين","أمثلة الرنين (7)"]},{"n":213,"lo":"U2","sec":"GS151-U2","type":"list","topic":"أسباب الهروب","stem":"يقول الكتاب إن الإنسان ما يلقى مفر إلا الهروب إلى الملعب رقم (4) بسبب ثلاث أشياء. أي وحدة مو منها؟","options":["إهمال اللعب في الملعب (1) حيث الأولويات","استمرار الضغط والاحتراق في ملعب (2)","قضاء أغلب الوقت في ملعب المهم غير العاجل","الاستجابة غير الواعية للرنين في ملعب (3)"],"answer":2,"why":"ص 32: الثلاثة: إهمال الملعب (1)، واستمرار الضغط والاحتراق في (2)، والاستجابة غير الواعية للرنين في (3). اللي يعيش في ملعب الأولويات هو السعيد (ص 33)، مو الهارب.","wrong":[{"i":0,"mis":"gen.partial","note":"هذا السبب الأول بالنص"},{"i":1,"mis":"gen.partial","note":"هذا السبب الثاني بالنص"},{"i":3,"mis":"gen.partial","note":"هذا السبب الثالث بالنص"}],"tests":["ملعب الهروب","أسباب الهروب (3)"]},{"n":214,"lo":"U2","sec":"GS151-U2","type":"concept","topic":"الناجحون والسعداء","stem":"حسب الكتاب، «السعداء» يقضون معظم أوقاتهم في:","options":["ملعبي المهم رقم (1) و(2)","ملعب المهم العاجل رقم (2)","ملعب المهم غير العاجل رقم (1)","ملعب غير المهم العاجل رقم (3)"],"answer":2,"why":"ص 33: الناجحون أكثر وقتهم في ملاعب المهم (1) و(2)، أما السعداء فمعظم وقتهم في ملعب المهم غير العاجل (1) بس.","wrong":[{"i":0,"mis":"g2.success-vs-happiness","note":"هذا وصف الناجحين، السعداء في (1) بس"},{"i":1,"mis":"g2.playground-numbering","note":"(2) ملعب الاحتراق، تقضي عمرك تطفي حرايق"},{"i":3,"mis":"gen.neighbor","note":"(3) الرنين، مهام تجذبك وهي غير مهمة"}],"tests":["الناجحون والسعداء","ملاعب الوقت"]},{"n":215,"lo":"U2","sec":"GS151-U2","type":"term","topic":"أولوية (أ)","stem":"«الأعمال التي لابد أن ننجزها غالبًا بأنفسنا، والرؤية التي نصوغها من خلال التخطيط الإستراتيجي وإدارة المستقبل» — هذي أولوية:","options":["(ب): المهمة والعاجلة","(أ): المهمة وغير العاجلة","(ج): العاجلة وغير المهمة","(د): غير المهمة وغير العاجلة"],"answer":1,"why":"ص 34: أولوية (أ) خاصة بالأعمال المهمة وغير العاجلة، ويتجاهلها أغلب الناس لأن نتايجها بعيدة المدى، ويحسبون ما له داعي للتخطيط دام الشغل ماشي، وما جربوها قبل.","wrong":[{"i":0,"mis":"g2.priority-a-urgent","note":"(ب) نسويها بإدارة الأزمات وأسلوب المطافئ، مو بالتخطيط الإستراتيجي"},{"i":2,"mis":"gen.neighbor","note":"(ج) نسويها لإرضاء الآخرين أو لأننا ما ندري إنها تافهة"},{"i":3,"mis":"gen.reversed","note":"(د) نتاج الوقت المهدر، عكس التخطيط تمامًا"}],"tests":["أولوية (أ)","أبجديات الأولويات"]},{"n":216,"lo":"U2","sec":"GS151-U2","type":"concept","topic":"الوصية الذهبية","stem":"«الوصية الذهبية» في أبجديات الأولويات هي:","options":["معظم الوقت للأولوية (ب)، وجزء كبير لـ(أ)، وأقل جزء لـ(ج)","توزيع الوقت بالتساوي على (أ) و(ب) و(ج)","معظم الوقت للأولوية (أ)، وجزء كبير لـ(ج)، وأقل جزء لـ(ب)","معظم الوقت للأولوية (أ)، وجزء كبير لـ(ب)، وأقل جزء لـ(ج)"],"answer":3,"why":"ص 34: بالنص: «استثمر معظم الوقت في إدارة الأولوية (أ)، وجزءًا كبيرًا من الوقت في إدارة الأولوية (ب)، وأقل جزء من الوقت للتعامل مع الأولوية (ج)». و(د) أصلًا نتخلص منها.","wrong":[{"i":0,"mis":"gen.reversed","note":"قلبت (أ) و(ب)، الأكثر دايم لـ(أ)"},{"i":1,"mis":"gen.absolute","note":"الوصية فيها ترتيب واضح، مو تساوي"},{"i":2,"mis":"gen.reversed","note":"(ج) غير مهمة، تاخذ أقل جزء مو جزء كبير"}],"tests":["الوصية الذهبية","أبجديات الأولويات"]},{"n":217,"lo":"U2","sec":"GS151-U2","type":"list","topic":"الأولوية (د)","stem":"كل التالي من أمثلة أنشطة الأولوية (د) في الكتاب ما عدا:","options":["التخطيط الإستراتيجي ووضع رؤية المستقبل","الاجتماعات الجانبية الناتجة عن صراع داخل المؤسسة","البطالة المقنعة اللي تأثر سلبًا على الروح المعنوية","الزيارات المفاجئة اللي تربك العمل"],"answer":0,"why":"ص 34: أمثلة (د) أربعة: الاتصالات التليفونية الشخصية للحديث في أي شي، والاجتماعات الجانبية من صراع داخل المؤسسة، والبطالة المقنعة، والزيارات المفاجئة. التخطيط الإستراتيجي هو أولوية (أ)، وهو نفسه اللي نقضي فيه على (د).","wrong":[{"i":1,"mis":"gen.partial","note":"من أمثلة (د) بالنص"},{"i":2,"mis":"gen.partial","note":"من أمثلة (د) بالنص"},{"i":3,"mis":"gen.partial","note":"من أمثلة (د) بالنص"}],"tests":["الأولوية (د)","أمثلة الأولوية (د) (4)"]},{"n":218,"lo":"U2","sec":"GS151-U2","type":"figure","topic":"الإنسان المضيع للوقت","stem":"في شكل «الإنسان المضيع للوقت» (ص 34)، كل الصفات التالية مكتوبة حوله ما عدا:","img":"img/gs151/U2-p034.png","options":["يسمح بالمقاطعة","لا يكتب فينسى","ضعيف التواصل مع الآخرين","يحدد أولوياته"],"answer":3,"why":"ص 34: الشكل فيه ثمان صفات: غير منظم، بلا أهداف، كسول، مسوّف، ضعيف التواصل مع الآخرين، لا يكمل عمله، يسمح بالمقاطعة، لا يكتب فينسى. تحديد الأولويات صفة اللي يدير وقته صح.","wrong":[{"i":0,"mis":"gen.partial","note":"موجودة في الشكل"},{"i":1,"mis":"gen.partial","note":"موجودة في الشكل، وهي سبب النسيان كعامل تضييع"},{"i":2,"mis":"gen.partial","note":"موجودة في الشكل"}],"tests":["صفات الإنسان المضيع للوقت (8)"]},{"n":219,"lo":"U2","sec":"GS151-U2","type":"scenario","topic":"عوامل تضييع الأوقات","stem":"سعود يبدأ مشروع ويوقف لما يخلص تقريبًا 80% منه، وينتقل لمشروع ثاني ويسوي نفس الشي، لين تتراكم عليه مشاريع شبه منتهية. حسب الكتاب، هذا عامل تضييع الوقت اسمه:","options":["عدم إكمال الأعمال","التكاسل والتأجيل","سوء الفهم للغير","الورق"],"answer":0,"why":"ص 35: العامل الخامس «عدم إكمال الأعمال»، والكتاب ذكر مثال الـ80% بالضبط، والحل: تخلص شغلك كامل بعدين تنتقل، وهذا يبي تركيز بس. أما «التكاسل والتأجيل» فهو أشد معوقات تنظيم الوقت بس هو عامل ثاني.","wrong":[{"i":1,"mis":"gen.neighbor","note":"التأجيل إنك تأخر البدء، وسعود يبدأ بس ما يكمل"},{"i":2,"mis":"gen.keyword","note":"سوء الفهم عن سوء إيصال المعاني للناس"},{"i":3,"mis":"gen.keyword","note":"الورق عن تراكم الأوراق بدون قرار"}],"tests":["عوامل تضييع الأوقات (7)","عدم إكمال الأعمال"]},{"n":220,"lo":"U2","sec":"GS151-U2","type":"term","topic":"تعريف التسويف","stem":"«أن تقوم بمهمة ذات أولوية منخفضة بدلا من أن تنجز مهمتك ذات الأولوية العالية، أو الميل لتأجيل أداء المهام...» — هذا تعريف:","options":["الهروب","الرنين","التسويف","عدم إكمال الأعمال"],"answer":2,"why":"ص 35: هذا تعريف التسويف، ويكمّل: «حتى الغد أو بعده بقليل، وفي مرحلتها النهائية عن طريق اختلاق الأعذار».","wrong":[{"i":0,"mis":"gen.neighbor","note":"الهروب ملعب (4) غير المهم غير العاجل"},{"i":1,"mis":"gen.neighbor","note":"الرنين أشياء عاجلة تسحبك كرد فعل"},{"i":3,"mis":"gen.neighbor","note":"عدم الإكمال تبدأ وتوقف قبل النهاية"}],"tests":["تعريف التسويف"]},{"n":221,"lo":"U2","sec":"GS151-U2","type":"list","topic":"أعراض التسويف","stem":"أي وحدة من التالي يذكرها الكتاب من «أعراض التسويف»؟","options":["ضع وقتًا محددًا للانتهاء من كل مهمة","الخوف من الفشل","ابدأ فورًا بالمهام اللي تأجلها دايم","اكتب قائمة بالأشياء اللي تأجلها دايم وحللها"],"answer":1,"why":"ص 35: أعراض التسويف خمسة: الاستجابة طواعية للعوائق والمقاطعات، وقضاء فترات طويلة في القهوة والشاي والغدا والمشاوير، والتركيز على الأعمال الثانوية، وقضاء وقت طويل في مهمة بسيطة، والخوف من الفشل. الباقي كلها طرق علاج (ص 35–36).","wrong":[{"i":0,"mis":"g2.symptom-vs-cure","note":"هذي أول طريقة علاج، مو عرض"},{"i":2,"mis":"g2.symptom-vs-cure","note":"هذي الطريقة الخامسة للعلاج"},{"i":3,"mis":"g2.symptom-vs-cure","note":"هذي الطريقة الثالثة للعلاج"}],"tests":["أعراض التسويف (5)","علاج التسويف (6)"]},{"n":222,"lo":"U2","sec":"GS151-U2","type":"scenario","topic":"علاج التسويف","stem":"ريم دايم تأجل مذاكرة الإحصاء. حسب الكتاب، «أفضل طريقة» تتعامل فيها مع المهام اللي تأجلها دايم:","options":["ترتب مكتبها زين قبل لا تبدأ","تخلص المهام الثانوية السهلة أول","تأجلها لآخر الأسبوع لين يصير عندها فراغ","تبدأ فيها فورًا"],"answer":3,"why":"ص 36: بالنص: «أفضل طريقة للتعامل مع المهام التي تؤجلها دائما هي أن تبدأ بها فورا»، ومعها حكمة «لا تؤجل عمل اليوم إلى الغد».","wrong":[{"i":0,"mis":"g2.symptom-vs-cure","note":"ترتيب المكان طويلًا قبل الشغل الصعب من صفات المسوفين"},{"i":1,"mis":"g2.symptom-vs-cure","note":"التركيز على الثانويات من أعراض التسويف"},{"i":2,"mis":"gen.reversed","note":"هذا هو التسويف نفسه"}],"tests":["علاج التسويف","صفات المسوفين"]},{"n":223,"lo":"U2","sec":"GS151-U2","type":"concept","topic":"قصة فنجان القهوة","stem":"في قصة فنجان القهوة، «الحصى» (الأحجار المتوسطة والصغيرة) يمثل:","options":["الأشياء الضرورية مثل دينك وقيمك وعائلتك وصحتك","الأمور البسيطة والهامشية","المساحة اللي تبقى دايم للاسترخاء","الأشياء المهمة حسب أهميتها مثل وظيفتك وبيتك وسيارتك ومالك"],"answer":3,"why":"ص 37: الزجاجة = الحياة. الأحجار الكبيرة = الضروري (دينك، قيمك، أخلاقك، عائلتك، أطفالك، صحتك، أصدقاءك). الحصى = المهم حسب أهميته (وظيفتك، بيتك، سيارتك، مالك، هواياتك). الرمل والماء = البسيط والهامشي. والقهوة = مساحة الاسترخاء (ص 38).","wrong":[{"i":0,"mis":"g2.rocks-vs-pebbles","note":"هذي الأحجار الكبيرة، مو الحصى"},{"i":1,"mis":"gen.neighbor","note":"هذا الرمل والماء"},{"i":2,"mis":"g2.coffee-meaning","note":"هذا فنجان القهوة"}],"tests":["قصة فنجان القهوة","الأحجار الكبيرة والحصى والرمل"]},{"n":224,"lo":"U2","sec":"GS151-U2","type":"figure","topic":"حديث الخط المربع","stem":"في الشكل اللي رسمه الرسول ﷺ للصحابة (ص 37)، الخط المربع المحيط بالإنسان يمثل:","img":"img/gs151/U2-p037.png","options":["الأمل","الأعراض","الإنسان","الأجل"],"answer":3,"why":"ص 37: حديث ابن مسعود: الخط الأوسط الإنسان، والخطوط اللي جنبه الأعراض تنهشه، والخط المربع «الأجل المحيط به»، والخط الخارج البعيد هو الأمل. يعني الأجل يقطع الأمل مهما كان.","wrong":[{"i":0,"mis":"gen.reversed","note":"الأمل الخط الخارج البعيد، مو المربع"},{"i":1,"mis":"gen.neighbor","note":"الأعراض الخطوط الصغيرة جنب الإنسان"},{"i":2,"mis":"gen.detail","note":"الإنسان الخط الأوسط داخل المربع"}],"tests":["حديث الخط المربع","حدود الحياة (4)"]},{"n":225,"lo":"U2","sec":"GS151-U2","type":"tf","topic":"معنى فنجان القهوة","stem":"في قصة فنجان القهوة، أضاف الأستاذ القهوة آخر شي عشان يوضح إن الأمور التافهة دايم تلقى لها مكان وتزاحم المهم.","options":["صح","خطأ"],"answer":1,"why":"ص 38: الأستاذ قال إنه أضاف القهوة عشان يوضح إنه «مهما كانت حياتك مليئة.. فسيبقى هناك دائمًا مساحة للاسترخاء مع فنجان من القهوة». التوافه في القصة هي الرمل والماء.","wrong":[{"i":0,"mis":"g2.coffee-meaning","note":"القهوة مساحة استرخاء، مو رمز للتوافه"}],"tests":["قصة فنجان القهوة"]},{"n":226,"lo":"U2","sec":"GS151-U2","type":"figure","topic":"هرم الأحجار الكبيرة","stem":"في «هرم الأحجار الكبيرة» (ص 38)، الحاجة إلى الحب هي احتياجات:","img":"img/gs151/U2-p038.png","options":["العقل","الجسد","النفس","الروح"],"answer":2,"why":"ص 38: الهرم من القاعدة للقمة: الحياة (احتياجات الجسد)، ثم الحب (احتياجات النفس: الجماعة والعلاقات والانتماء)، ثم التعلم (احتياجات العقل)، وفوق ترك الأثر (حاجات الروح)، ومكتوب عليها في الشكل «الذكر».","wrong":[{"i":0,"mis":"g2.pyramid-order","note":"العقل للتعلم"},{"i":1,"mis":"g2.pyramid-order","note":"الجسد للحياة، قاعدة الهرم"},{"i":3,"mis":"g2.pyramid-order","note":"الروح لترك الأثر، قمة الهرم"}],"tests":["هرم الأحجار الكبيرة","الحاجات الأربع"]},{"n":301,"lo":"U3","sec":"GS151-U3","type":"term","topic":"تعريف القرار","stem":"«الاختيار الواعي والدقيق لأحد البدائل المتاحة، في الوقت المناسب لتحقيق الأهداف المرجوة» — هذا تعريف:","options":["المشكلة","حل المشكلة","التنفيذ","القرار"],"answer":3,"why":"هذا تعريف القرار في ص 43، ومنه تطلع أركانه الثلاثة: الاختيار الواعي، البدائل المتاحة، الأهداف المرجوة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المشكلة = عائق أو موقف يحول بينك وبين أهدافك (ص 49)"},{"i":1,"mis":"gen.neighbor","note":"حل المشكلة = عملية تفكير مركب تستخدم فيها خبراتك ومهاراتك (ص 49)"},{"i":2,"mis":"gen.neighbor","note":"التنفيذ = وضع القرار موضع التطبيق بإلزام أشخاص بمهام محددة (ص 64)"}],"tests":["تعريف القرار"]},{"n":302,"lo":"U3","sec":"GS151-U3","type":"list","topic":"أركان القرار","stem":"حسب الكتاب، تعريف القرار يضم ثلاثة أركان أساسية، هي:","options":["الاختيار الواعي، البدائل المتاحة، الأهداف المرجوة","الصبر، الأفضل، المخاطرة","المواجهة، المعلومات، الصياغة","الاختيار الواعي، المخاطرة، الأهداف المرجوة"],"answer":0,"why":"ص 43: التعريف يضم ٣ أركان: الاختيار الواعي (أداته العقل)، البدائل المتاحة (أكثر من بديل)، الأهداف المرجوة (جزرة التحفيز). أما الصبر والأفضل والمخاطرة فهي أركان صناعة القرار في الرسم الدائري.","wrong":[{"i":1,"mis":"g3.arkan-mix","note":"هذي أركان صناعة القرار في الرسم الدائري، مو أركان القرار"},{"i":2,"mis":"g3.stage-order","note":"هذي خطوات المرحلة الأولى (تحديد المشكلة)"},{"i":3,"mis":"gen.partial","note":"دخلت المخاطرة مكان البدائل المتاحة"}],"tests":["أركان القرار","أركان صناعة القرار"]},{"n":303,"lo":"U3","sec":"GS151-U3","type":"concept","topic":"القرارات المبرمجة وغير المبرمجة","stem":"حسب جدول المقارنة في الكتاب، أي وصف ينطبق على القرارات المبرمجة؟","options":["غير متكررة ودرجة عدم التأكد فيها عالية","بدائلها كثيرة وغير نمطية ومخاطرتها مرتفعة","متكررة وروتينية، بدائلها قليلة ونمطية، ومخاطرتها منخفضة أو منعدمة","أداتها الأساليب الحديثة في حل المشكلات والتفكير الابتكاري"],"answer":2,"why":"جدول ص 44: المبرمجة متكررة وروتينية وفيها درجة عالية من التأكد، بدائلها قليلة ونمطية، مخاطرتها منخفضة أو منعدمة، وأداتها العادة والقواعد الروتينية، مثل الذهاب للعمل وشراء الملابس.","wrong":[{"i":0,"mis":"g3.programmed-flip","note":"هذا وصف غير المبرمجة"},{"i":1,"mis":"g3.programmed-flip","note":"بدائل كثيرة ومخاطرة مرتفعة = غير المبرمجة"},{"i":3,"mis":"g3.programmed-flip","note":"التفكير الابتكاري أداة غير المبرمجة، المبرمجة أداتها العادة"}],"tests":["القرارات المبرمجة","القرارات غير المبرمجة"]},{"n":304,"lo":"U3","sec":"GS151-U3","type":"list","topic":"عيوب الأسلوب المحافظ","stem":"كل التالي من عيوب الأسلوب المحافظ في اتخاذ القرار ما عدا:","options":["الانحصار في عدد محدود من البدائل وفي مسار واحد","أن البحث عن المثالية أكبر وسيلة للضياع","أن الخبرة تتعلق بالماضي بينما اتخاذ القرار يرتبط بالمستقبل","تقديس الآباء والرموز والصراع حولهم"],"answer":1,"why":"عيوب المحافظ الخمسة في ص 45: الانحصار في بدائل محدودة، الخبرة ماضي والقرار مستقبل، الاعتماد على خبرة الماضي ما يتيح المبادأة، التطور العلمي أتاح أدوات جديدة، وتقديس الآباء والرموز. أما «البحث عن المثالية أكبر وسيلة للضياع» فهو اعتراض على الأسلوب العلمي (ص 45).","wrong":[{"i":0,"mis":"gen.partial","note":"هذا أول عيب من عيوب المحافظ الخمسة"},{"i":2,"mis":"gen.partial","note":"هذا العيب الثاني فعلًا"},{"i":3,"mis":"gen.partial","note":"هذا العيب الخامس، ويودي للفرقة وأمراض الفريق"}],"tests":["عيوب الأسلوب المحافظ","الأسلوب العلمي"]},{"n":305,"lo":"U3","sec":"GS151-U3","type":"term","topic":"القرار المرضي","stem":"الأسلوب اللي يقوم على سلوك الرجل الإداري (Administrative Man) ويدور القرار الأنسب (What Satisfies is good enough) هو:","options":["الأسلوب العلمي اللي سماه سيد عليوة (النموذج الراشد)","الأسلوب المحافظ عند ليندبلوم","القرار المُرضي","النظرية التوفيقية عند إتزيوني"],"answer":2,"why":"ص 46: القرار المُرضي شكل ثاني من الأسلوب العلمي، يقوم على سلوك الرجل الإداري ويدور القرار الأنسب والمُرضي، فهو محقق للرضا وأكثر واقعية من الرجل الاقتصادي.","wrong":[{"i":0,"mis":"g3.economic-vs-admin","note":"العلمي = الرجل الاقتصادي اللي يدور المثالية، مو الرضا"},{"i":1,"mis":"g3.theorist-swap","note":"المحافظ يرجع للقرارات السابقة والتقليد"},{"i":3,"mis":"g3.theorist-swap","note":"التوفيقية تمزج العقلانية والتراكمية وتفرق بين قرارات أساسية وثانوية"}],"tests":["القرار المرضي","الرجل الإداري","الرجل الاقتصادي"]},{"n":306,"lo":"U3","sec":"GS151-U3","type":"tf","topic":"أنماط اتخاذ القرارات","stem":"حسب صندوق «أنماط اتخاذ القرارات»، النمط الثالث هو اتخاذ القرارات بالدراسة والتحليل.","options":["صح","خطأ"],"answer":1,"why":"ص 47: النمط الأول بالخبرة والإحساس الشخصي، الثاني بالدراسة والتحليل، والثالث بمزيج من الإحساس والدراسة، وهو اللي توصل له نظرية إتزيوني التوفيقية.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الدراسة والتحليل هي النمط الثاني، مو الثالث"}],"tests":["أنماط اتخاذ القرارات"]},{"n":307,"lo":"U3","sec":"GS151-U3","type":"concept","topic":"القرارات الأساسية والثانوية","stem":"في النظرية التوفيقية لإتزيوني، القرارات الثانوية هي:","options":["قرارات مهمة واستراتيجية أثرها بعيد (long range) وتتخذ على أساس عقلاني","قرارات أقل أهمية أثرها قصير (short range)، تركز على التفاصيل وتتخذ على أساس تراكمي","قرارات أقل أهمية أثرها قصير، وتتخذ على أساس عقلاني بدون تفاصيل","قرارات متكررة وروتينية مخاطرتها منعدمة"],"answer":1,"why":"ص 47: الثانوية أقل أهمية وأثرها قصير (short range)، تندرس بدايلها في ضوء القرارات الأساسية السابقة، تركز على التفاصيل، وتتخذ على أساس تراكمي. ومثالها كاميرا الطقس اللي تصور القطاع الصغير بتفاصيل كثيرة.","wrong":[{"i":0,"mis":"g3.basic-secondary","note":"هذا وصف القرارات الأساسية"},{"i":2,"mis":"g3.basic-secondary","note":"الثانوية تراكمية وتركز على التفاصيل، والعقلاني للأساسية"},{"i":3,"mis":"g3.programmed-flip","note":"هذا وصف القرارات المبرمجة، تقسيم ثاني"}],"tests":["القرارات الثانوية","القرارات الأساسية","النظرية التوفيقية"]},{"n":308,"lo":"U3","sec":"GS151-U3","type":"scenario","topic":"احذر أن تتخذ القرار","stem":"سارة انرفض طلبها، وعلاقتها بمن حولها مو طيبة، وفقدت أهم مساعديها، فقالت: الحين بأبدأ آخذ قراراتي. حسب الكتاب، هذا الموقف:","options":["من المواقف العشرة اللي يحذر منها الكتاب، لأنها قرارات إحباط","أنسب وقت للقرار لأنها صارت تشوف المشكلة بحجمها الطبيعي","تطبيق لخطوة المرونة لأنها رجعت لدائرة صنع القرار","مثال على الأسلوب المحافظ لأنها تعتمد على خبرة الفشل"],"answer":0,"why":"ص 47 «احذر أن تتخذ القرار»: الموقف الخامس «لقد رُفض طلبك.. وعلاقتك بمن حولك غير طيبة.. وفقدت أهم مساعديك.. الآن ابدأ في قرارات الإحباط». القايمة مكتوبة بسخرية، واللي يسويها يكون فشل في اتخاذ القرار.","wrong":[{"i":1,"mis":"gen.reversed","note":"حالتها هنا إحباط، مو رؤية متزنة للمشكلة"},{"i":2,"mis":"g3.stage-order","note":"المرونة (الخطوة ٩) تجي بعد تنفيذ قرار ثبت عدم صلاحيته"},{"i":3,"mis":"gen.keyword","note":"المحافظ يرجع لقرارات سابقة، والموقف هنا إحباط"}],"tests":["احذر أن تتخذ القرار"]},{"n":309,"lo":"U3","sec":"GS151-U3","type":"figure","topic":"خريطة حل المشكلات واتخاذ القرارات","stem":"حسب خريطة حل المشكلات واتخاذ القرارات (٩ خطوات في ٣ مراحل)، أي ربط صحيح؟","img":"img/gs151/U3-p048.png","options":["الصياغة: الخطوة الرابعة في المرحلة الثانية","المتابعة والتقييم: الخطوة السادسة في المرحلة الثانية","إنتاج الأفكار: الخطوة الثالثة في المرحلة الأولى","تقييم البدائل: الخطوة الخامسة في المرحلة الثانية (اتخاذ القرار)"],"answer":3,"why":"خريطة ص 48: المرحلة الأولى (ما المشكلة؟) = المواجهة، المعلومات، الصياغة. الثانية (اتخاذ القرار) = إنتاج الأفكار، تقييم البدائل، الاختيار. الثالثة (إصدار القرار) = التنفيذ، المتابعة والتقييم، المرونة.","wrong":[{"i":0,"mis":"g3.stage-order","note":"الصياغة الخطوة الثالثة وآخر المرحلة الأولى"},{"i":1,"mis":"g3.stage-order","note":"المتابعة والتقييم الخطوة الثامنة في المرحلة الثالثة، والسادسة = الاختيار"},{"i":2,"mis":"g3.stage-order","note":"إنتاج الأفكار الخطوة الرابعة وأول المرحلة الثانية"}],"tests":["خريطة حل المشكلات","مراحل وخطوات القرار"]},{"n":310,"lo":"U3","sec":"GS151-U3","type":"concept","topic":"أصناف الناس أمام المشكلات","stem":"حسب الكتاب، مين اللي يُقدم على اتخاذ القرار من أصناف الناس أمام المشكلات؟","options":["اللي يستصغر المشكلة وشعاره No problem","اللي يضخم المشكلة وشعاره لا فائدة","اللي يشوف المشكلة في حجمها الطبيعي وشعاره لكل مشكلة حل","اللي يعتبر أدنى انحراف عن النموذج مشكلة"],"answer":2,"why":"ص 48–49: الصنفين الأولين (No problem، والتضخيم) ما يتخذون القرار. اللي يتخذونه هم الصنف الأخير، ويتميزون بـ ٣ رؤى: فيه مشكلة واضحة، يشوفونها بحجمها الطبيعي، وكل مشكلة لها حل.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا الصنف الأول، والمشاكل تتراكم عنده من اللامبالاة"},{"i":1,"mis":"gen.neighbor","note":"هذا الصنف الثاني، يضيع وقته في الدعاية للمشكلة"},{"i":3,"mis":"gen.absolute","note":"هذا صنف مزعج يطلب المثالية المستحيلة أو قلق (ص 49)"}],"tests":["أصناف الناس أمام المشكلات","رؤى متخذ القرار"]},{"n":311,"lo":"U3","sec":"GS151-U3","type":"term","topic":"تعريف المشكلة","stem":"«عائق أو موقف يحول بين الفرد وتحقيق أهدافه» — هذا تعريف:","options":["المشكلة","حل المشكلة","المشكلة الفرعية","العناصر الحاكمة"],"answer":0,"why":"ص 49: «المشكلة هي عائق أو موقف يحول بين الفرد وتحقيق أهدافه». أما حل المشكلة فهو «عملية تفكير مركب يستخدم فيه الفرد خبراته ومهاراته للوصول الى نتيجة».","wrong":[{"i":1,"mis":"gen.neighbor","note":"حل المشكلة عملية تفكير مركب، مو عائق"},{"i":2,"mis":"g3.symptom-vs-problem","note":"الفرعية عرض مؤقت ينتج من المشكلة الحقيقية"},{"i":3,"mis":"gen.neighbor","note":"العناصر الحاكمة عوامل لو توفرت أمكن حل المشكلة"}],"tests":["تعريف المشكلة","تعريف حل المشكلة"]},{"n":312,"lo":"U3","sec":"GS151-U3","type":"figure","topic":"معايير الأهداف","stem":"في رسم الإنجاز والزمن (معايير الأهداف)، أي انحراف عن الخط المثالي يعتبر غير مقبول ونقدر نقول عنده: لدينا مشكلة؟","img":"img/gs151/U3-p049.png","options":["(أ)","(هـ)","(ج)","(ب)"],"answer":1,"why":"ص 49: الخط المستقيم = المعيار المثالي، والخط المنكسر = الأداء. الانحراف (أ) و(ج) مقبول فما نقول فيه مشكلة، أما (هـ) فانحراف غير مقبول = مشكلة. و(ب) قمة فوق الخط = امتياز.","wrong":[{"i":0,"mis":"gen.detail","note":"(أ) انحراف مقبول، ومكتوب تحته لا مشكلة"},{"i":2,"mis":"gen.detail","note":"(ج) بعد انحراف مقبول = لا مشكلة"},{"i":3,"mis":"gen.reversed","note":"(ب) فوق الخط = امتياز، وما تبان مشكلة إلا لو المعيار خيالي"}],"tests":["معايير الأهداف","المعيار المثالي","الانحراف المقبول وغير المقبول"]},{"n":313,"lo":"U3","sec":"GS151-U3","type":"concept","topic":"المشكلة الحقيقية والفرعية","stem":"وش الفرق بين المشكلة الحقيقية والمشكلة الفرعية حسب الكتاب؟","options":["الحقيقية عرض مؤقت يختفي بسرعة، والفرعية هي العقبة الرئيسية","الحقيقية هي العقبة الرئيسية اللي تعوق تحقيق الأهداف وما يتحقق الهدف إلا بحلها، والفرعية عرض مؤقت ينتج منها ويختفي باختفائها","الحقيقية تخص الفرد، والفرعية تخص المجموعة","ما فيه فرق، والاثنتين لازم تنحل كل وحدة لحالها عشان يتحقق الهدف"],"answer":1,"why":"ص 50: «فالمشكلة الحقيقية: هي العقبة الرئيسية التي تعوق تحقيق الأهداف. ولا يتحقق الهدف إلا بحلها» و«المشكلة الفرعية: هي عرض مؤقت ينتج من المشكلة الحقيقية ويختفي باختفائها». ولو حددت الحقيقية صح، تروح جهودك لها مو لأعراضها.","wrong":[{"i":0,"mis":"g3.symptom-vs-problem","note":"قلبت التعريفين"},{"i":2,"mis":"gen.detail","note":"التقسيم مو فرد ومجموعة، التقسيم سبب وعرض"},{"i":3,"mis":"g3.symptom-vs-problem","note":"الفرعية تختفي لحالها لما تنحل الحقيقية"}],"tests":["المشكلة الحقيقية","المشكلة الفرعية"]},{"n":314,"lo":"U3","sec":"GS151-U3","type":"list","topic":"سمات المعلومة الجيدة","stem":"سمات المعلومة الجيدة الأربع حسب الكتاب هي:","options":["الصلة بالموضوع، التوقيت المناسب، الشرعية والقانونية، الدقة","الصلة بالموضوع، الكثرة، السرعة، الدقة","التنبؤات، البيانات، الكمية، الوصفية","موثقة، محددة، متوافقة، مختصرة"],"answer":0,"why":"صندوق ص 51: سمات المعلومة الجيدة = الصلة بالموضوع، التوقيت المناسب، الشرعية والقانونية، الدقة، وهي نفسها ضوابط جمع المعلومات في ص 52.","wrong":[{"i":1,"mis":"gen.partial","note":"الكثرة والسرعة مو منها، والمعلومة المبكرة ممكن تضر"},{"i":2,"mis":"g3.data-types","note":"هذي أنواع المعلومات، مو سماتها"},{"i":3,"mis":"gen.partial","note":"موثقة ومحددة ومتوافقة تفاصيل سمة الدقة بس، ومختصرة مو منها"}],"tests":["سمات المعلومة الجيدة","ضوابط جمع المعلومات"]},{"n":315,"lo":"U3","sec":"GS151-U3","type":"tf","topic":"ضوابط جمع المعلومات: التوقيت","stem":"حسب ضابط التوقيت، المعلومة اللي توصل قبل موعدها المناسب بمدة ممكن تشكل خطورة، فهي ممكن ما تفيد وممكن تضر بعد.","options":["صح","خطأ"],"answer":0,"why":"ص 52: المعلومة اللي تجي بعد موعدها ما لها فايدة تقريبًا، و«إذا جاءت المعلومة قبل موعدها بمدة فإنها تشكل خطورة فهي قد لا تفيد فقط ولكن قد تضر أيضا»، وأكثر المعلومات فايدة اللي تجي في موعدها المناسب.","wrong":[{"i":1,"mis":"gen.partial","note":"الكتاب يقول المبكرة ممكن تضر، مو بس ما تفيد"}],"tests":["ضوابط جمع المعلومات","التوقيت"]},{"n":316,"lo":"U3","sec":"GS151-U3","type":"scenario","topic":"أنواع البيانات","stem":"طالب يدرس مشكلة الغياب في كليته، ولقى إحصائية جمعتها عمادة القبول لغرض ثاني، بس تصلح يستفيد منها في موضوعه. هذي البيانات تعتبر:","options":["بيانات أولية","بيانات تاريخية","تنبؤات وتوقعات","بيانات ثانوية"],"answer":3,"why":"ص 52: البيانات الثانوية «جمعت لأغراض أخرى وتصلح للموضوع» وما تتعلق فيه مباشرة بس تصلح للاستفادة. الأولية تنجمع خصيصًا للموضوع (مثل الاستبانة)، والتاريخية لفترات أو خبرات أو أفراد سابقين.","wrong":[{"i":0,"mis":"g3.data-types","note":"الأولية تنجمع خصيصًا للموضوع نفسه"},{"i":1,"mis":"g3.data-types","note":"التاريخية تخص فترات أو خبرات أو أفراد سابقين"},{"i":2,"mis":"g3.data-types","note":"التنبؤات تعتمد على الحدس والتخمين، مو بيانات مجموعة"}],"tests":["أنواع البيانات","البيانات الثانوية"]},{"n":317,"lo":"U3","sec":"GS151-U3","type":"figure","topic":"سمكة إيشيكاوا","stem":"في مخطط سمكة إيشيكاوا لمشكلة «ضعف مستوى التعليم»، وش يمثل رأس السمكة ووش تمثل العظام الرئيسية؟","img":"img/gs151/U3-p053.png","options":["الرأس = النتيجة المطلوب تحليلها (ضعف مستوى التعليم) على يمين الصفحة، والعظام الرئيسية = العوامل الرئيسية مثل الأسرة والإداريين والطلبة","الرأس = الحل المقترح، والعظام = خطوات التنفيذ بالترتيب","الرأس = السبب الرئيسي، والعظام = النتائج المترتبة عليه","الرأس = أهم عامل، والعظام الرئيسية = الأعراض المؤقتة للمشكلة"],"answer":0,"why":"ص 53: تحدد النتيجة وتكتبها يمين الصفحة كرأس السمكة، ترسم خط أفقي تطلع منه العظام الرئيسية وتكتب عليها العوامل الرئيسية (الأسرة، الإداريون، الطلبة)، والأسباب تنكتب كعظام ثانوية، وبعدين تحدد العامل الأهم وتجمع بيانات للتأكد.","wrong":[{"i":1,"mis":"g3.tool-mix","note":"خطوات التنفيذ المتتابعة أقرب لخرائط التدفق وبيرت"},{"i":2,"mis":"gen.reversed","note":"قلبت السبب والنتيجة، الرأس هو النتيجة"},{"i":3,"mis":"g3.symptom-vs-problem","note":"العظام عوامل وأسباب، مو أعراض"}],"tests":["سمكة إيشيكاوا","تحليل السبب والنتيجة"]},{"n":318,"lo":"U3","sec":"GS151-U3","type":"scenario","topic":"أدوات تحليل وعرض المعلومات","stem":"تبي توضح كم يمثل كل بند (أكل، مواصلات، كتب) من مجموع مصروفك الشهري، يعني علاقة الجزء بالكل. أنسب أداة حسب الكتاب:","options":["المدرجات التكرارية","خرائط باي (Pie Charts)","خرائط بيرت","خرائط التدفق"],"answer":1,"why":"ص 54: خرائط باي «تستخدم في توضيح علاقة الجزء بالكل وكيف يسهم الجزء في الناتج الكلي». المدرج أعمدة توضح توزيع خاصية، بيرت للوقت والتكلفة، والتدفق للمدخلات والأنشطة ونقاط القرار والمخرجات.","wrong":[{"i":0,"mis":"g3.tool-mix","note":"المدرج أعمدة توضح توزيع خاصية مثل أوزان الطلاب"},{"i":2,"mis":"g3.tool-mix","note":"بيرت تدير الوقت والتكلفة للأنشطة"},{"i":3,"mis":"g3.tool-mix","note":"التدفق توضح خطوات عملية ونقاط القرار فيها"}],"tests":["أدوات تحليل وعرض المعلومات","خرائط باي"]},{"n":319,"lo":"U3","sec":"GS151-U3","type":"term","topic":"العناصر الحاكمة","stem":"في خطوة صياغة المشكلة، «العوامل التي لو توفرت لأمكن حل المشكلة» اسمها:","options":["الأعراض المرتبطة بالمشكلة","تحليل ظروف المشكلة","المعيار المثالي","العناصر الحاكمة (Critical Factors)"],"answer":3,"why":"ص 55: تشخيص المشكلة يحتاج أمرين: تحديد العناصر الحاكمة Critical Factors «وهي العوامل التي لو توفرت لأمكن حل المشكلة»، ودقة صياغة المشكلة.","wrong":[{"i":0,"mis":"g3.symptom-vs-problem","note":"الأعراض نفرقها عن المشكلة، مو هي اللي تحلها"},{"i":1,"mis":"gen.neighbor","note":"تحليل الظروف خطوة من خطوات الصياغة (الحالية والمرغوبة والطرق)"},{"i":2,"mis":"gen.neighbor","note":"المعيار المثالي الخط اللي نقيس عليه الانحراف (ص 49)"}],"tests":["العناصر الحاكمة","خطوات صياغة المشكلة"]},{"n":320,"lo":"U3","sec":"GS151-U3","type":"concept","topic":"أساليب العصف الذهني","stem":"في جلسة عصف ذهني، رئيس الجلسة يأشر على الأعضاء واحد واحد عشان كل واحد يقول فكرته، واللي ما عنده فكرة يعدّي، وبعدين يرجع له مرة ثانية. هذا أسلوب:","options":["الانطلاق الحر","القصاصات","التناوب","تقييم الأفكار أول بأول"],"answer":2,"why":"ص 57: أسلوب التناوب «يشير رئيس الجلسة إلى الأعضاء بالتناوب ليقول فكرته ويعبر من لا يحمل فكرة حاضرة» ويرجع لهم أكثر من مرة. الانطلاق الحر = كل واحد يطرح فكرته أول ما تطلع، والقصاصات = يكتبون أفكارهم على أوراق.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الانطلاق الحر بدون دور، أي أحد يطرح فكرته وقت ما تجي"},{"i":1,"mis":"gen.neighbor","note":"القصاصات كتابة الأفكار على أوراق"},{"i":3,"mis":"g3.brainstorm-judge","note":"الحكم على الأفكار ممنوع قبل ما يكتمل الطرح (ص 58)"}],"tests":["العصف الذهني","أساليب العصف الذهني"]},{"n":321,"lo":"U3","sec":"GS151-U3","type":"term","topic":"أنواع البدائل","stem":"البديل اللي «لا يتوقع أن تكون له عيوب (سلبيات) أو مزايا (إيجابيات)» هو:","options":["البديل المختلط (Mixed)","البديل الضعيف (Poor)","البديل غير المجدي (Bland)","البديل الجيد (Good)"],"answer":2,"why":"ص 58: الجيد مزاياه أكثر من عيوبه، الضعيف عيوبه أكثر، المختلط تكاد تتساوى عيوبه ومزاياه، وغير المجدي (Bland) ما يُتوقع له عيوب ولا مزايا.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المختلط فيه عيوب ومزايا بس متساوية تقريبًا"},{"i":1,"mis":"gen.neighbor","note":"الضعيف عيوبه أكثر من مزاياه"},{"i":3,"mis":"gen.neighbor","note":"الجيد مزاياه أكثر من عيوبه"}],"tests":["أنواع البدائل","تقييم البدائل"]},{"n":322,"lo":"U3","sec":"GS151-U3","type":"figure","topic":"الترتيب التقييمي للبدائل","stem":"في مثال شراء السيارة، بعد ما أعطينا كل معيار وزن وضربنا الدرجات فيه (جدول وزن المعايير)، أي سيارة جابت أعلى مجموع وصارت الأولى؟","img":"img/gs151/U3-p060.png","options":["أ","ب","ج","د"],"answer":2,"why":"جدول ص 60: مجموع ج×و = ٤٠ وهو الأعلى، وج كانت الأولى بعد في الترتيب المبدئي (١٤). ووزن المعايير غيّر ترتيب باقي السيارات (ص 61).","wrong":[{"i":0,"mis":"gen.detail","note":"أ كانت الثانية في الترتيب المبدئي (١٢) بس مو الأولى بعد الوزن"},{"i":1,"mis":"gen.detail","note":"ب كانت الأخيرة في الترتيب المبدئي (٩)"},{"i":3,"mis":"gen.detail","note":"د مجموعها بعد الوزن ٣٢، أقل من ج"}],"tests":["الترتيب التقييمي للبدائل","وزن المعايير"]},{"n":323,"lo":"U3","sec":"GS151-U3","type":"tf","topic":"عملية الطرح","stem":"المعيار الأساسي اللي قيّم فيه إبراهيم عليه السلام البدائل (الأصنام، الكواكب، القمر، الشمس) هو الأفول، يعني الغياب وعدم الوجود.","options":["صح","خطأ"],"answer":0,"why":"ص 61–62: إبراهيم عليه السلام طرح البدائل وقيّمها بمعيار الأفول أي الغياب وعدم الوجود، وبعد طرح كل البدائل بقى بديل واحد: عبادة الله الواحد، وهذي عملية الطرح في خطوة الاختيار.","wrong":[{"i":1,"mis":"gen.detail","note":"المعيار فعلًا الأفول، والشمس ميزتها كبرها بس وهي بعد تأفل"}],"tests":["عملية الطرح","الاختيار واتخاذ القرار"]},{"n":324,"lo":"U3","sec":"GS151-U3","type":"scenario","topic":"فاعلية القرار","stem":"قرار (أ) نوعيته ٨ ومدى قبوله ٢، وقرار (ب) نوعيته ٦ ومدى قبوله ٤. حسب معادلة الكتاب، وش الصح؟","options":["(ب) أفعل: فاعليته ٢٤ مقابل ١٦ لـ(أ)","(أ) أفعل لأن نوعيته أعلى","الاثنين نفس الفاعلية: ١٠ لكل واحد","ما نقدر نقارن لأن الفاعلية تعتمد على الجودة بس"],"answer":0,"why":"ص 62: «فاعلية القرار= النوعية × مدى القبول» → (أ) = ٨×٢ = ١٦، (ب) = ٦×٤ = ٢٤. ترتفع الفاعلية كل ما ارتفع القبول حتى لو قلت الجودة، والحل الوسط المقبول غالبًا أفعل من الحل الصحيح المرفوض.","wrong":[{"i":1,"mis":"g3.effectiveness-quality","note":"الجودة لحالها ما تحدد الفاعلية، لازم تضربها في القبول"},{"i":2,"mis":"g3.effectiveness-quality","note":"جمعت بدل ما تضرب، والمعادلة ضرب"},{"i":3,"mis":"g3.effectiveness-quality","note":"الكتاب يقول الجودة مو العامل الوحيد، فيه مدى القبول"}],"tests":["فاعلية القرار","قبول القرار"]},{"n":325,"lo":"U3","sec":"GS151-U3","type":"concept","topic":"اتخاذ وصناعة وإصدار القرار","stem":"حسب الكتاب، عبارة «اتخاذ القرار» تدل على:","options":["العملية كلها من أولها إلى آخرها لين يتحقق الهدف","الخطوات الثلاث في المرحلة الثانية: ابتكار البدائل، تقييمها، ثم الاختيار","المرحلة الثالثة: التنفيذ والمتابعة والمرونة","الخطوات التسع كاملة، وهي نفسها حل المشكلات"],"answer":1,"why":"ص 63: صناعة القرار = العملية كلها، واتخاذ القرار = الخطوة السادسة، والكاتب يشوفها تدل على خطوات المرحلة الثانية الثلاث (ابتكار البدائل، تقييمها، الاختيار)، وإصدار القرار = المرحلة الثالثة. وحل المشكلات ينتهي بست خطوات، وصناعة القرار تكتمل بتسع.","wrong":[{"i":0,"mis":"g3.decision-terms","note":"هذي صناعة القرار"},{"i":2,"mis":"g3.decision-terms","note":"هذي إصدار القرار"},{"i":3,"mis":"g3.decision-terms","note":"حل المشكلات ٦ خطوات بس، والتسع = صناعة القرار"}],"tests":["اتخاذ القرار","صناعة القرار","إصدار القرار"]},{"n":326,"lo":"U3","sec":"GS151-U3","type":"term","topic":"تعريف التنفيذ","stem":"«وضع القرار موضع التطبيق بإلزام شخص أو أشخاص معينين بأداء مهام محددة.. في وقت معين ولفترة زمنية محددة.. باستخدام إمكانات مادية محددة» — هذا تعريف:","options":["التنفيذ","إصدار القرار","المتابعة والتقييم","المرونة"],"answer":0,"why":"ص 64: هذا تعريف التنفيذ. وأول قواعده «التأكد من مشاركة كل من بإمكانه المساهمة في صنع القرار»، والقرار الناجح «الذي تكون خطة تنفيذه جزءًا منه».","wrong":[{"i":1,"mis":"g3.decision-terms","note":"إصدار القرار المرحلة الثالثة كلها، والقرار المُصدَر فيه ٦ فقرات"},{"i":2,"mis":"g3.stage-order","note":"المتابعة والتقييم الخطوة الثامنة، تقارن الإنجاز بالأهداف"},{"i":3,"mis":"g3.stage-order","note":"المرونة = الرجوع لدائرة القرار لتصحيح المسار"}],"tests":["تعريف التنفيذ"]},{"n":327,"lo":"U3","sec":"GS151-U3","type":"list","topic":"فقرات القرار المصدر","stem":"القرار اللي يصدر لازم يحتوي على عدة فقرات. وحدة من التالي مو منها:","options":["نص القرار، ومن يجب إبلاغه القرار","التخطيط للعمل، وتحديد المسؤوليات","الجدول الزمني، ومصادر الميزانية","خطبة تحفيزية تأجج عواطف المنفذين"],"answer":3,"why":"ص 64: فقرات القرار الست: نص القرار، من يجب إبلاغه، التخطيط للعمل، تحديد المسؤوليات، الجدول الزمني، مصادر الميزانية. والكتاب يقول عن الإصدار: «فهو ليس خطة استمالة أو تأجيج عواطف».","wrong":[{"i":0,"mis":"gen.partial","note":"هذول أول فقرتين"},{"i":1,"mis":"gen.partial","note":"هذول الفقرة الثالثة والرابعة"},{"i":2,"mis":"gen.partial","note":"هذول الفقرة الخامسة والسادسة"}],"tests":["فقرات إصدار القرار"]},{"n":328,"lo":"U3","sec":"GS151-U3","type":"tf","topic":"الدائرة المغلقة","stem":"في الدائرة المغلقة، لو ظهرت أثناء التنفيذ مشاكل جديدة ينقصها الحل، نرجع للخطوة الثانية (جمع المعلومات).","options":["صح","خطأ"],"answer":1,"why":"ص 67: الدائرة المغلقة = عند كل خطوة تنفيذية نرجع للخطوة اللي توازيها: المقارنة بالوضع المرغوب ← الخطوة الأولى، الحاجة للبيانات ← الخطوة الثانية، ومشاكل جديدة ينقصها الحل ← الخطوة الخامسة (تقييم البدائل).","wrong":[{"i":0,"mis":"g3.stage-order","note":"الخطوة الثانية للحاجة للبيانات، والمشاكل الجديدة ترجعك للخامسة"}],"tests":["الدائرة المغلقة","المتابعة والتقييم"]},{"n":1001,"lo":"U2","sec":"GS151-PRAC","type":"scenario","topic":"مصفوفة الوقت – ملعب الأولويات","stem":"عندما تخطط لنيل درجة البكالوريوس في مدة 4 سنوات، وتعكف لتحقيق هذا الهدف، فأنت في ملعب","options":["الهروب","الأولويات","الرنين","الاحتراق"],"answer":1,"why":"ص34: أولوية (أ) = المهم غير العاجل، وهي التخطيط الاستراتيجي وإدارة المستقبل. خطة 4 سنين للبكالوريوس مهمة بس مو مستعجلة، فأنت في ملعب الأولويات (رقم 1 بالرسم ص32).","wrong":[{"i":0,"mis":"gen.neighbor","note":"الهروب للأشياء اللي لا مهمة ولا عاجلة، وهدف البكالوريوس مهم."},{"i":2,"mis":"g2.urgent-means-important","note":"الرنين أشياء عاجلة غير مهمة تجذبك، وهنا العكس: مهم وغير عاجل."},{"i":3,"mis":"gen.neighbor","note":"الاحتراق لما المهم يصير عاجل بآخر لحظة، وأنت لسه مخطط من بدري."}],"tests":["مصفوفة الوقت","ملعب الأولويات","المهم غير العاجل"]},{"n":1002,"lo":"U1","sec":"GS151-PRAC","type":"list","topic":"تحقيق الأهداف: تحويلها لأنشطة","stem":"في حال تحويل أهدافك إلى أنشطة يجب عليك استخدام إحدى الخطوات التالية","options":["تسجيل جميع نجاحاتك السابقة","تغيير بعض ملامح الأهداف إن احتجت إلى ذلك","الاستمتاع بشعور الإنجاز","البحث عن مرشد"],"answer":3,"why":"ص14–15: خطوات «حوّل الأهداف لأنشطة» هي: جزّئ الهدف، استخدم العصف الذهني، اكتسب طاقة للتنفيذ، ابحث عن مرشد (رقم 4 أول ص15)، المعلومات، كن إيجابي. الباقي كله من قسم «على طريق التنفيذ».","wrong":[{"i":0,"mis":"gen.neighbor","note":"تسجيل النجاحات السابقة من «ثانيًا: على طريق التنفيذ» ص15، مو من تحويل الأهداف لأنشطة"},{"i":1,"mis":"g1.goals-flexible","note":"تغيير ملامح الأهداف بند في «على طريق التنفيذ» ص15، مو خطوة تحويل لأنشطة"},{"i":2,"mis":"gen.neighbor","note":"الاستمتاع بشعور الإنجاز برضو من «على طريق التنفيذ» ص15"}],"tests":["خطوات تحويل الأهداف لأنشطة","التفريق بين القائمتين: حوّل لأنشطة vs على طريق التنفيذ"]},{"n":1003,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"أدوار الحياة (مجالات الأهداف)","stem":"«تريد أن تجعل الحياة جميلة من حولك» يمثل ذلك دورا:","options":["خدمة المجتمع","روحيا","أسريا","نفسيا"],"answer":0,"why":"ص11: دور خدمة المجتمع نصّه «تريد أن تجعل الحياة من حولك أجمل، كيف تخطط لهذا؟».","wrong":[{"i":1,"mis":"gen.neighbor","note":"الروحي يخص علاقتك مع الله وفروضها ونوافلها"},{"i":2,"mis":"gen.neighbor","note":"الأسري عن الأسرة اللي ترعاها وصورتك مع عائلتك"},{"i":3,"mis":"gen.neighbor","note":"النفسي عن المشاكل اللي ترجعك ورا وتحسين سلوكك"}],"tests":["أدوار الحياة التسعة","دور خدمة المجتمع"]},{"n":1004,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"أساليب اتخاذ القرار","stem":"التقليدية من أبرز صفات أصحاب النمط","options":["التوافقي","المرضي","المحافظ","العلمي"],"answer":2,"why":"ص45: من السمات الشخصية لأصحاب الأسلوب المحافظ «ضعف القدرة على الابتكار» و«الروح المحافظة التقليدية». يعني التقليدية = المحافظ.","wrong":[{"i":0,"mis":"gen.neighbor","note":"التوفيقي يمزج بين العقلاني والتراكمي، ما هو نمط التقليد"},{"i":1,"mis":"g3.economic-vs-admin","note":"المرضي هو الرجل الإداري يرضى بالقرار الواقعي المناسب، ماله دخل بالتقليد"},{"i":3,"mis":"gen.reversed","note":"العلمي يدور القرار الأمثل بالتحليل والدقة، عكس التقليد تماماً"}],"tests":["الأسلوب المحافظ","سمات أصحاب الأسلوب المحافظ"]},{"n":1005,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"طبيعة الوقت – الوقت محدود","stem":"عندما تقول \"أنك لا تستطيع أن تخزن جزء من الوقت للاستخدام في وقت لاحق\". يعني ذلك خاصية من خصائص طبيعة الوقت، هي:","options":["محدود","يجري","غال","ينمو"],"answer":0,"why":"ص20–21: تحت «٢- الوقت محدود» الكتاب يقول «لا بد من إدراك الحقائق الآتية»: كلنا عندنا 168 ساعة بالأسبوع، وما تقدر تخزّن جزء من الوقت لوقت لاحق، وما تقدر توقفه أو تسرّعه، وما تصرفه إلا بمعدله. كلها قبل عنوان «تعويض الوقت»، فهي من خاصية المحدود.","wrong":[{"i":1,"mis":"g2.facts-under-runs","note":"«يجري» يعني يمضي بسرعة لما تحتاجه، والحقائق هذي مكتوبة تحت «محدود» مو تحت «يجري»."},{"i":2,"mis":"gen.neighbor","note":"«غالٍ» عن قيمة الوقت كنعمة، مو عن إنه ما ينخزن."},{"i":3,"mis":"gen.reversed","note":"«نمو الوقت» يعني تزيد قيمته بالاستثمار، عكس فكرة الحد."}],"tests":["طبيعة الوقت","الوقت محدود","حقائق الوقت"]},{"n":1006,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"هرم الأحجار الكبيرة – الحاجة إلى التعلم","stem":"الحاجة إلى التعلم من ضمن :","options":["الحاجات الصحية","الحاجات العقلية","الحاجات الروحية","الحاجات الامنية"],"answer":1,"why":"ص38: الحاجة إلى التعلم = احتياجات العقل من المعرفة والحكمة والخبرات والمهارات. يعني حاجات عقلية.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الصحة والعافية تبع «حاجات الحياة» (احتياجات الجسد)، مو التعلم."},{"i":2,"mis":"gen.neighbor","note":"حاجات الروح هي «ترك الأثر» بقمة الهرم، مو التعلم."},{"i":3,"mis":"gen.keyword","note":"الأمنية ما هي من الأربع حاجات في هرم الأحجار أصلاً."}],"tests":["هرم الأحجار الكبيرة","الحاجة إلى التعلم","احتياجات العقل"]},{"n":1007,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"صفات الإنسان المضيع للوقت","stem":"من صفات الشخص المضيع لوقته أنه","options":["يشتغل بالأولويات","يكتب مهامه","يحدد أهدافه","التسويف والاتكالية"],"answer":3,"why":"ص34: رسمة «الإنسان المضيع للوقت» فيها: كسول، مسوّف، بلا أهداف، غير منظم، لا يكتب فينسى… فالتسويف والاتكالية (الكسل) هي صفته.","wrong":[{"i":0,"mis":"gen.reversed","note":"الاشتغال بالأولويات صفة الناجح، المضيع يشتغل بالثانويات."},{"i":1,"mis":"gen.reversed","note":"المضيع «لا يكتب فينسى»، يعني العكس تماماً."},{"i":2,"mis":"gen.reversed","note":"المضيع «بلا أهداف»، فتحديد الأهداف عكس صفته."}],"tests":["مضيعات الوقت","صفات المضيع للوقت"]},{"n":1008,"lo":"U1","sec":"GS151-PRAC","type":"term","topic":"مرادفات الهدف","stem":"الأمر الذي يرغب الإنسان في تحقيقه لكنه لا يضع برنامجا لإنجازه يسمى","options":["هدف","غاية","أمنية","حلم"],"answer":2,"why":"ص9: الأمنية = أمر تبي تحققه بس ما تحط له برنامج عملي لتحقيقه أو إنجازه.","wrong":[{"i":0,"mis":"g1.elements-vs-pillars","note":"الهدف من عناصره إنك تخطط لتنفيذه ص8، يعني فيه برنامج"},{"i":1,"mis":"g1.ghaya-level","note":"الغاية أعلى درجات الأهداف وأكثرها طموح، مو شي بلا برنامج"},{"i":3,"mis":"g1.umniya-vs-hulm","note":"الحلم تبيه بس تستبعد يصير، فيظل متنقل بين الحلم والأمنية"}],"tests":["الأمنية","الفرق بين الأمنية والحلم والغاية"]},{"n":1009,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"علاج التسويف","stem":"من الطرق العلاجية لسارق الوقت أي \"مرض التسويف\"","options":["كتابة قائمة بالمهام مرتبة","إنجاز الأعمال الثانوية المزعجة","الخوف من الفشل","البدء بالأحجار الصغيرة جداً"],"answer":0,"why":"ص35–36 تحت «كيف نقضي على التسويف»: حط وقت محدد لكل مهمة، خذ على نفسك عهد ما تأجل، واكتب قائمة بالأشياء اللي دايم تأجلها وحللها ولاحظ النمط. فكتابة القائمة هي الخيار الوحيد اللي من العلاج، والباقي أعراض أو غلط.","wrong":[{"i":1,"mis":"g2.symptom-vs-cure","note":"التركيز على الأعمال الثانوية وغير المهمة هو العرض رقم 3 للتسويف ص35، مو علاجه."},{"i":2,"mis":"g2.symptom-vs-cure","note":"الخوف من الفشل العرض رقم 5 للتسويف، مو علاج."},{"i":3,"mis":"g2.rocks-vs-pebbles","note":"الكتاب يقول «ابدأ بالأحجار الكبيرة» ص36، مو الصغيرة."}],"tests":["التسويف","علاج التسويف","أعراض التسويف"]},{"n":1010,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"ضوابط الهدف الأكثر فاعلية","stem":"وضعت ليلى لنفسها هدفا أن لا تترك ممارسة الرياضة لمدة ساعة أسبوعيا، تقل فاعلية هذا الهدف لأنه","options":["استعملت النفي في صياغته","غير واقعي","غير قابل للقياس","غير قابل للتحقيق"],"answer":0,"why":"ص13 ضابط رقم 2: لا تستعمل النفي في صياغة أهدافك، قل «أن أفعل كذا» ولا تقول «أن لا أفعل كذا». ليلى قالت «أن لا تترك».","wrong":[{"i":1,"mis":"gen.neighbor","note":"ساعة بالأسبوع شي واقعي جدًا"},{"i":2,"mis":"gen.neighbor","note":"فيه رقم واضح: ساعة أسبوعيًا، يعني ينقاس"},{"i":3,"mis":"g1.attainable-vs-realistic","note":"ساعة بالأسبوع في قدرة أي أحد، المشكلة بالصياغة مو بالتحقيق"}],"tests":["عدم استخدام النفي في صياغة الهدف"]},{"n":1011,"lo":"U3","sec":"GS151-PRAC","type":"scenario","topic":"أساليب اتخاذ القرار","stem":"عندما يقوم شخص باتخاذ القرارات بناء على خبرات الآخرين فهو يتصف بأنه:","options":["علمي","توفيقي","محافظ","مغامر"],"answer":2,"why":"ص44: ليندبلوم يقول صاحب الأسلوب المحافظ يرجع للقرارات السابقة اللي اتخذها هو «أو اتخذها غيره» ويدور تجارب في نفس الموضوع. فالاعتماد على خبرات الآخرين = محافظ.","wrong":[{"i":0,"mis":"gen.reversed","note":"العلمي يجمع معلومات ويقيّم البدائل بعقلانية، ما يمشي على تجارب غيره"},{"i":1,"mis":"g3.theorist-swap","note":"تجارب الآخرين هي نظرية ليندبلوم (المحافظ)، والتوفيقي لإتزيوني جا بعدها ومزج الطريقتين"},{"i":3,"mis":"gen.neighbor","note":"«مغامر» مو من الأساليب الأربعة بالكتاب أصلاً"}],"tests":["الأسلوب المحافظ","ليندبلوم"]},{"n":1012,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"صياغة المشكلة","stem":"لصياغة جيدة للمشكلة تحتاج إلى","options":["تحليل المشكلة لأجزائها الدقيقة","حل المشكلة","توقع حل المشكلة","تجاهل المشكلة"],"answer":0,"why":"ص56: أول خطوة من خطوات صياغة المشكلة «تحليل المشكلة» يعني تجزئتها لمكوناتها الفرعية ووحداتها الأساسية.","wrong":[{"i":1,"mis":"g3.stage-order","note":"الحل يجي بعدين في المرحلة الثانية، الصياغة قبله"},{"i":2,"mis":"g3.stage-order","note":"توقع الحل مو من خطوات الصياغة؛ الصياغة تحليل وظروف وأعراض"},{"i":3,"mis":"gen.reversed","note":"تجاهل المشكلة عكس المطلوب تماماً"}],"tests":["خطوات صياغة المشكلة","تحليل المشكلة"]},{"n":1013,"lo":"U3","sec":"GS151-PRAC","type":"list","topic":"أركان القرار","stem":"جميع ما يأتي يعد من أركان القرار ماعدا:","options":["تحديد الأهداف المرجوة","وجود بدائل متاحة","الاختيار الواعي","تحمل المخاطرة"],"answer":3,"why":"ص43: أركان القرار ثلاثة: الاختيار الواعي، البدائل المتاحة، الأهداف المرجوة. المخاطرة من أركان «صانع القرار» (الصبر، الأفضل، المخاطرة) مو من أركان القرار نفسه.","wrong":[{"i":0,"mis":"g3.arkan-mix","note":"الأهداف المرجوة الركن الثالث من أركان القرار"},{"i":1,"mis":"g3.arkan-mix","note":"البدائل المتاحة الركن الثاني من أركان القرار"},{"i":2,"mis":"g3.arkan-mix","note":"الاختيار الواعي الركن الأول من أركان القرار"}],"tests":["أركان القرار","أركان صانع القرار"]},{"n":1014,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"أنواع الأهداف من حيث الزمن","stem":"يسعى خالد إلى تخفيض وزنه، حيث وضع لنفسه هدفاً بأن يمارس الرياضة لمدة ساعتين يومياً، إن هدف خالد يعد هدفاً:","options":["متوسطة المدى","إجرائي","طويل المدى","قصير المدى"],"answer":1,"why":"ص9: الأهداف الإجرائية (التشغيلية) هي أهداف صغيرة تصير مجرد أنشطة شهرية أو أسبوعية أو يومية وتنكتب في قائمة المهام To Do list. ساعتين رياضة كل يوم نشاط يومي، فهو إجرائي. القصير المدى هو الهدف الأكبر (أقل من 3 سنين) اللي يتقسم لهالأنشطة، وهذا واضح في رسمة ص9 (قصير ← إجرائي). القاعدة: كلمة «يومياً/أسبوعياً/شهرياً» = إجرائي.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المتوسط بين 3 و10 سنين ومرتبط بمرحلة زي الجامعة"},{"i":2,"mis":"g1.long-term-span","note":"الطويل فوق 10 سنين، مو نشاط يومي"},{"i":3,"mis":"g1.operational-todo","note":"القصير أقل من 3 سنين وهو اللي يتقسم لأنشطة، أما النشاط اليومي نفسه فاسمه إجرائي"}],"tests":["الأهداف الإجرائية","أنواع الأهداف الأربعة"]},{"n":1015,"lo":"U3","sec":"GS151-PRAC","type":"scenario","topic":"أنواع القرارات","stem":"من أمثلة القرارات غير المبرمجة:","options":["الطلاق","المذاكرة للاختبار","تناول الطعام","شراء الملابس"],"answer":0,"why":"ص44: القرارات غير المبرمجة غير متكررة وغير روتينية ومخاطرها مرتفعة، وأمثلتها بالكتاب الزواج واختيار التخصص. الطلاق من نفس النوع: قرار مصيري ما يتكرر.","wrong":[{"i":1,"mis":"g3.programmed-flip","note":"المذاكرة شي متكرر وروتيني = مبرمج"},{"i":2,"mis":"g3.programmed-flip","note":"الأكل يومي وروتيني = مبرمج"},{"i":3,"mis":"g3.programmed-flip","note":"شراء الملابس يتكرر ومخاطره قليلة = مبرمج"}],"tests":["القرارات المبرمجة وغير المبرمجة"]},{"n":1016,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"أنواع البيانات","stem":"هي البيانات التي تجمع خصيصا للموضوع","options":["البيانات التاريخية","البيانات الأولية","البيانات الكمية","البيانات الثانوية"],"answer":1,"why":"ص52 جدول البيانات: الأولية «تجمع خصيصاً للموضوع» مثل الاستبانة.","wrong":[{"i":0,"mis":"g3.data-types","note":"التاريخية تتعلق بفترات أو خبرات سابقة"},{"i":2,"mis":"g3.data-types","note":"الكمية تصنيف حسب الشكل الرقمي، مو حسب سبب الجمع"},{"i":3,"mis":"g3.data-types","note":"الثانوية انجمعت لأغراض ثانية وتصلح للموضوع"}],"tests":["البيانات الأولية","أنواع البيانات"]},{"n":1017,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"هرم الأحجار الكبيرة – القاعدة","stem":"الحاجة التي تقع في قاعدة هرم الأحجار الكبيرة هي:","options":["الحاجة إلى ترك الأثر","حاجات الحياة","الحاجة إلى التعلم","الحاجة إلى الحب"],"answer":1,"why":"ص38: الهرم من القاعدة للقمة: الحياة ← الحب ← التعلم ← ترك الأثر. فالقاعدة حاجات الحياة (احتياجات الجسد).","wrong":[{"i":0,"mis":"g2.pyramid-order","note":"ترك الأثر بالقمة مو بالقاعدة."},{"i":2,"mis":"g2.pyramid-order","note":"التعلم ثالث من تحت، تحت ترك الأثر مباشرة."},{"i":3,"mis":"g2.pyramid-order","note":"الحب ثاني من تحت، فوق الحياة."}],"tests":["هرم الأحجار الكبيرة","ترتيب الحاجات","حاجات الحياة"]},{"n":1018,"lo":"U1","sec":"GS151-PRAC","type":"term","topic":"أنواع الأهداف من حيث الزمن","stem":"قوائم المهام هي مرادف للأهداف:","options":["متوسطة المدى","القصيرة","الإجرائية","بعيدة المدة"],"answer":2,"why":"ص9: الأهداف الإجرائية أو التشغيلية هي اللي نكتبها في قوائم المهام (To Do – list).","wrong":[{"i":0,"mis":"gen.neighbor","note":"المتوسطة مرتبطة بمرحلة زي الجامعة (3–10 سنين)"},{"i":1,"mis":"g1.operational-todo","note":"القصيرة أقل من 3 سنين، أما قوائم المهام فهي الإجرائية"},{"i":3,"mis":"g1.long-term-span","note":"البعيدة هي أهداف العمر فوق 10 سنين"}],"tests":["الأهداف الإجرائية = To Do list"]},{"n":1019,"lo":"U3","sec":"GS151-PRAC","type":"list","topic":"صياغة المشكلة","stem":"(تحليل المشكلة، تحليل ظروف المشكلة، تحليل الأعراض المرتبطة بالمشكلة)، الخطوات السابقة تشير إلى خطوة من خطوات حل المشكلات واتخاذ القرارات هي","options":["صياغة المشكلة","جمع المعلومات","تحليل المعلومات","مواجهة المشكلة"],"answer":0,"why":"ص56: «خطوات صياغة المشكلة»: تحليل المشكلة، تحليل ظروف المشكلة، تحديد الأعراض المرتبطة بالمشكلة. وهي الخطوة الثالثة بالخريطة ص48.","wrong":[{"i":1,"mis":"g3.stage-order","note":"جمع المعلومات الخطوة الثانية، والتحليلات الثلاث تحت الصياغة"},{"i":2,"mis":"gen.keyword","note":"كلمة «تحليل» خدعتك؛ العناوين الثلاثة هي خطوات صياغة المشكلة"},{"i":3,"mis":"g3.stage-order","note":"المواجهة أول خطوة (تحديد المشكلة) مو هذي"}],"tests":["خطوات صياغة المشكلة","خريطة حل المشكلات"]},{"n":1020,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"أدوار الحياة (مجالات الأهداف)","stem":"عندما تسأل نفسك: (هل هناك أي معرفة جديدة تريد أن تكتسبها؟ ما المهارات والمعلومات التي تحتاجها لتحقيق الكثير من أهدافك ؟) فإنك تحدد أداءك في الدور:","options":["التعليمي","خدمة المجتمع","النفسي","الترفيهي"],"answer":0,"why":"ص11: الدور التعليمي أسئلته: فيه معرفة جديدة تبي تكتسبها؟ تسعى لدرجة علمية؟ وش المهارات والمعلومات اللي تحتاجها؟","wrong":[{"i":1,"mis":"gen.neighbor","note":"خدمة المجتمع = تبي تخلي الحياة حولك أجمل"},{"i":2,"mis":"gen.neighbor","note":"النفسي = مشاكل ترجعك ورا وتحسين سلوكك"},{"i":3,"mis":"gen.neighbor","note":"الترفيهي = جزء من حياتك لك، وش أفضل أسلوب تستمتع فيه"}],"tests":["الدور التعليمي","أسئلة كل دور"]},{"n":1021,"lo":"U1","sec":"GS151-PRAC","type":"concept","topic":"ضوابط الهدف الأكثر فاعلية","stem":"من الأمور التي تساعد على تحقيق الأهداف الشخصية","options":["الاحتفاظ بها ذهنياً دون الإفصاح عنها","تجزئة الأهداف وكتابتها بدقة","تأجيلها قدر المستطاع","طلب المساعدة من صديق لكتابتها"],"answer":1,"why":"ص13–14: كن أكثر دقة عند الكتابة، استخدم الورق (الكتابة تخليها في دائرة اهتمامك)، واجعل الأهداف الإجرائية صغيرة، وأول خطوة لتحويل الهدف لأنشطة: جزّئ الهدف.","wrong":[{"i":0,"mis":"gen.reversed","note":"الكتاب يقول استخدم الورق واكتبها، مو تخليها بس في راسك"},{"i":2,"mis":"gen.reversed","note":"التأجيل عكس التحقيق، والكتاب يقول حط وقت للبداية والنهاية"},{"i":3,"mis":"g1.own-goals","note":"لا تدع أحد يضع لك أهدافك، أنت أعرف الناس بقدراتك ص14"}],"tests":["الكتابة والدقة","تجزئة الهدف","لا تدع أحد يضع لك أهدافك"]},{"n":1022,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"هرم الأحجار الكبيرة – التعلم","stem":"في هرم الأحجار الكبيرة فان احتياجات العقل من المعرفة والحكمة والخبرات تندرج ضمن الحاجة إلى:","options":["التعلم","الحياة","الحب","ترك الأثر"],"answer":0,"why":"ص38: «الحاجة إلى التعلم: وهي احتياجات العقل من المعرفة والحكمة والخبرات والمهارات والقدرات».","wrong":[{"i":1,"mis":"gen.neighbor","note":"الحياة = احتياجات الجسد (صحة وعافية وطعام)."},{"i":2,"mis":"gen.neighbor","note":"الحب = احتياجات النفس والعلاقات مع الناس."},{"i":3,"mis":"gen.neighbor","note":"ترك الأثر = حاجات الروح ومعنى الحياة."}],"tests":["هرم الأحجار الكبيرة","الحاجة إلى التعلم"]},{"n":1023,"lo":"U3","sec":"GS151-PRAC","type":"scenario","topic":"الاختيار واتخاذ القرار","stem":"استخدم نبي الله إبراهيم عليه السلام في حواره مع قومه حول عبادة الأصنام ....","options":["مرونة التفكير","طرح البدائل","إصدار القرار","جمع المعلومات"],"answer":1,"why":"ص61: الكتاب جاب نقاش إبراهيم عليه السلام مع قومه كنموذج عملي لـ«عملية الطرح»: عرض البدائل (الأصنام، الكواكب، القمر، الشمس) وطرحها وحدة وحدة بمعيار الأفول.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المرونة الخطوة التاسعة وتخص خطط الطوارئ بعد التنفيذ"},{"i":2,"mis":"g3.decision-terms","note":"إصدار القرار المرحلة الثالثة (التنفيذ)، والقصة مثال على طرح البدائل"},{"i":3,"mis":"g3.stage-order","note":"جمع المعلومات الخطوة الثانية، والقصة عن الاختيار بين بدائل"}],"tests":["عملية الطرح","طرح البدائل"]},{"n":1024,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"العلاقة بين المشكلة والقرار","stem":"يسمى الإنسان صانع قرارات لأنه:","options":["يتخذ القرارات بصورة مستمرة في حياته اليومية","يمتلك القدرة على اتخاذ قرارات صحيحة","لديه القدرة على تعلم كيفية اتخاذ القرارات","لأنه يتخذ القرارات المساعدة في حل المشكلات"],"answer":0,"why":"ص42: اتخاذ القرارات «عملية مستمرة وملازمة للإنسان في جميع مراحل حياته» ولهالسبب نسمي الإنسان صانع القرارات Decision Maker.","wrong":[{"i":1,"mis":"gen.absolute","note":"الكتاب ما قال قراراته دايماً صحيحة؛ السبب الاستمرارية"},{"i":2,"mis":"gen.neighbor","note":"التعلم مهم بس مو هو سبب التسمية"},{"i":3,"mis":"gen.partial","note":"مو بس قرارات حل المشكلات، كل قراراته اليومية المستمرة"}],"tests":["صانع القرارات","اتخاذ القرار عملية مستمرة"]},{"n":1025,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"أساليب اتخاذ القرار","stem":"الدقة والعقلانية في القرار من سمات أصحاب النمط","options":["العلمي","المحافظ","التوافقي","المرضي"],"answer":0,"why":"ص45: الأسلوب العلمي (النموذج الراشد) يقوم على سلوك الرجل الاقتصادي «اللي يتحرى الدقة» ويختار البديل الأكثر عقلانية.","wrong":[{"i":1,"mis":"gen.reversed","note":"المحافظ يعتمد على التجربة والخطأ والتقليد"},{"i":2,"mis":"gen.neighbor","note":"التوفيقي ياخذ العقلانية للقرارات الأساسية بس ويمزجها بالتراكمي"},{"i":3,"mis":"g3.economic-vs-admin","note":"المرضي (الرجل الإداري) يتنازل عن المثالية ويرضى بالمناسب"}],"tests":["الأسلوب العلمي","الرجل الاقتصادي"]},{"n":1026,"lo":"U1","sec":"GS151-PRAC","type":"concept","topic":"أنواع الأهداف من حيث الزمن","stem":"حينما يحرص الفرد على القيام بأنشطة يومية فإنه بذلك يكون قد يحقق أهدافا:","options":["إجرائية أو تشغيلية","متوسطة المدى.","قصيرة المدى","طويلة المدى."],"answer":0,"why":"ص9: الإجرائية أو التشغيلية هي الأهداف الصغيرة اللي تصير أنشطة شهرية أو أسبوعية أو يومية.","wrong":[{"i":1,"mis":"gen.neighbor","note":"المتوسطة مرتبطة بمرحلة معينة زي الجامعة"},{"i":2,"mis":"g1.operational-todo","note":"القصيرة أقل من 3 سنين، والأنشطة اليومية اسمها إجرائية"},{"i":3,"mis":"g1.long-term-span","note":"الطويلة أهداف العمر فوق 10 سنين"}],"tests":["الأهداف الإجرائية"]},{"n":1027,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"جمع المعلومات","stem":"عند جمع المعلومات لابد أن تكون","options":["ذات صلة بالموضوع","غير معلومة المصدر","سطحية جداً","معقدة ومتشابكة"],"answer":0,"why":"ص51-52: سمات المعلومة الجيدة وضوابط جمعها: الصلة بالموضوع، التوقيت المناسب، الشرعية، الدقة. وأولها «صلة المعلومة بالموضوع».","wrong":[{"i":1,"mis":"gen.reversed","note":"لازم تكون موثقة وشرعية، مو مجهولة المصدر"},{"i":2,"mis":"gen.reversed","note":"المطلوب الدقة، مو السطحية"},{"i":3,"mis":"gen.reversed","note":"المعلومة لازم تكون محددة وواضحة، مو معقدة ومتشابكة"}],"tests":["ضوابط جمع المعلومات","سمات المعلومة الجيدة"]},{"n":1028,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"طبيعة الوقت – تعويض الوقت","stem":"قول الشاعر \"ألا ليت الشباب يعود يوماً فأخبره بما فعل المشيب\"، يدل قول الشاعر على أن الوقت:","options":["يجري","ينمو","لا يمكن تعويضه","محدود"],"answer":2,"why":"ص21: تحت «تعويض الوقت» سأل: هل يمكن تعويض الوقت؟ وجاوب ببيت الشاعر هذا. يعني اللي راح ما يرجع.","wrong":[{"i":0,"mis":"gen.neighbor","note":"«يجري» عن سرعة مضي الوقت، والبيت عن إنه ما يرجع."},{"i":1,"mis":"gen.neighbor","note":"«ينمو» عن زيادة قيمته بالاستثمار، ما له دخل بالبيت."},{"i":3,"mis":"gen.neighbor","note":"«محدود» عن الـ168 ساعة والتخزين، والبيت مستشهد فيه تحت التعويض."}],"tests":["طبيعة الوقت","تعويض الوقت"]},{"n":1029,"lo":"U1","sec":"GS151-PRAC","type":"list","topic":"ضوابط الهدف الأكثر فاعلية","stem":"إحدى العبارات الآتية لا تعد من الضوابط التي توضع ليكون الهدف أكثر فاعلية، هي:","options":["الدقة في كتابة الهدف","وضع الهدف الواحد في جملة واحدة","استخدام النفي في صياغة الهدف","ترتيب الأولويات"],"answer":2,"why":"ص13: الضابط رقم 2 يقول «لا تستعمل» النفي في الصياغة، فاستخدام النفي مو من الضوابط. الباقي (جملة واحدة، الدقة، رتب أولوياتك) كلها ضوابط.","wrong":[{"i":0,"mis":"gen.neighbor","note":"«كن أكثر دقة عند كتابة الوقت والتاريخ والكمية» ضابط رقم 3"},{"i":1,"mis":"gen.neighbor","note":"«ضع الهدف الواحد في جملة واحدة» ضابط رقم 1"},{"i":3,"mis":"g1.abc-priority","note":"«رتب أولوياتك» بأبجدية الأولويات ضابط رقم 4"}],"tests":["ضوابط الهدف الأكثر فاعلية","عدم استخدام النفي"]},{"n":1030,"lo":"U3","sec":"GS151-PRAC","type":"list","topic":"أركان القرار","stem":"من أركان اتخاذ القرار:","options":["الاختيار العاطفي","الاهداف المرجوة","التهور والتسرع","البديل الواحد"],"answer":1,"why":"ص43: أركان القرار: الاختيار الواعي، البدائل المتاحة، الأهداف المرجوة.","wrong":[{"i":0,"mis":"gen.keyword","note":"الركن هو الاختيار «الواعي» مو العاطفي"},{"i":2,"mis":"gen.reversed","note":"التسرع عكس الصبر المطلوب، مو ركن"},{"i":3,"mis":"gen.reversed","note":"الكتاب يقول البديل الواحد ما يؤدي إلى قرار؛ لازم أكثر من بديل"}],"tests":["أركان القرار"]},{"n":1031,"lo":"U2","sec":"GS151-PRAC","type":"scenario","topic":"مصفوفة الوقت – مهم وغير عاجل","stem":"البراء أحد الطلاب في شعبة مقرر مهارات الحياة الجامعية، ولديه اختبار نهائي بعد ثلاثة شهور، حيث كان يتابع المقرر ويدرسه بشكل يومي وبانتظام، يعد استعداد البراء للاختبار في هذا الوقت ضمن أحد مربعات مصفوفة الوقت الآتية، هو:","options":["غير مهم وغير عاجل","غير مهم وعاجل","مهم وغير عاجل","مهم وعاجل"],"answer":2,"why":"ص34: أولوية (أ) المهم غير العاجل: أشياء لازم ننجزها بأنفسنا من بدري بالتخطيط. الاختبار مهم بس باقي له 3 شهور، والبراء يذاكر أول بأول، فهو في المهم غير العاجل.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا ملعب الهروب، والمذاكرة للنهائي مهمة أكيد."},{"i":1,"mis":"g2.urgent-means-important","note":"غير المهم العاجل = الرنين (مكالمات وزيارات)، مو مذاكرة مخططة."},{"i":3,"mis":"gen.neighbor","note":"يصير مهم وعاجل لو أجّل لليلة الاختبار، بس هو باقي له 3 شهور."}],"tests":["مصفوفة الوقت","ملعب الأولويات","المهم غير العاجل"]},{"n":1032,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"النظرية التوفيقية","stem":"القرارات الثانوية وذات الأثر القصير، يتم أخذ القرارات فيها حسب النظرية التوفيقية على أساس:","options":["عقلاني","تراكمي","عاطفي","التجارب السابقة"],"answer":1,"why":"ص47: القرارات الثانوية (short range) تركز على التفاصيل «ويتم اتخاذها على أساس تراكمي».","wrong":[{"i":0,"mis":"g3.basic-secondary","note":"العقلاني للقرارات الأساسية ذات الأثر البعيد"},{"i":2,"mis":"gen.neighbor","note":"إتزيوني ما ذكر أساس عاطفي"},{"i":3,"mis":"g3.theorist-swap","note":"التجارب السابقة أساس نظرية ليندبلوم كلها، مو تقسيم إتزيوني"}],"tests":["النظرية التوفيقية","القرارات الثانوية"]},{"n":1033,"lo":"U2","sec":"GS151-PRAC","type":"scenario","topic":"مصفوفة الوقت – ملعب الاحتراق","stem":"أذن لصلاة المغرب، لكن سهام كانت مشغولة بمكالمة مهمة استمرت فيها حتى غاب الشفق الأحمر، هذا الموقف جعل سهام في ملعب:","options":["الهروب","البدائل","الاحتراق","الرنين"],"answer":2,"why":"ص30–31: مثال «أو شيء آخر!!»: تأجل الصلاة لين يضيق وقتها وتسارع وتتخبط. الكتاب يقول المهمة المهمة اللي تهملها في ملعب (1) تنتقل تلقائياً لملعب (2) الاحتراق (مهم وعاجل). سهام أخرت المغرب لين غاب الشفق يعني وقتها خلص تقريباً، فالصلاة صارت مهمة وعاجلة = احتراق.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الهروب للأشياء اللي لا مهمة ولا عاجلة، والصلاة مهمة وصارت عاجلة."},{"i":1,"mis":"gen.keyword","note":"«البدائل» مو ملعب أصلاً، هي من الوحدة الثالثة (القرارات). الملاعب: الاحتراق، الصيانة الوقائية، الرنين، الهروب."},{"i":3,"mis":"g2.urgent-means-important","note":"الرنين للعاجل غير المهم. السؤال عن الصلاة اللي ضاق وقتها، وهي مهمة، فهذا احتراق مو رنين."}],"tests":["مصفوفة الوقت","ملعب الاحتراق","إهمال الأولويات"]},{"n":1034,"lo":"U1","sec":"GS151-PRAC","type":"term","topic":"أنواع الأهداف من حيث الزمن","stem":"أهداف العمر مثال نموذجي للأهداف :","options":["طويلة المدى","متوسطة المدى","قصيرة المدى","إجرائية"],"answer":0,"why":"ص9: الأهداف طويلة المدى زمنها فوق 10 سنين وتسمى أهداف العمر أو الأهداف المرحلية.","wrong":[{"i":1,"mis":"gen.neighbor","note":"المتوسطة 3–10 سنين ومرتبطة بمرحلة زي الجامعة"},{"i":2,"mis":"g1.short-vs-near","note":"القصيرة أقل من 3 سنين، مو أهداف عمر"},{"i":3,"mis":"g1.operational-todo","note":"الإجرائية أنشطة يومية وأسبوعية في قائمة المهام"}],"tests":["الأهداف طويلة المدى = أهداف العمر"]},{"n":1035,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"هرم الأحجار الكبيرة – الحب","stem":"العلاقات مع الآخرين، تعد حسب تصنيف الأحجار الكبيرة من حاجات:","options":["التعلم","الحياة","الحب","ترك الأثر"],"answer":2,"why":"ص38: الحاجة إلى الحب = احتياجات النفس، وتدخل تحتها العلاقات مع الآخرين والانتماء وإنك تكون محبوب.","wrong":[{"i":0,"mis":"gen.neighbor","note":"التعلم احتياجات العقل (معرفة وخبرات)."},{"i":1,"mis":"gen.neighbor","note":"الحياة احتياجات الجسد."},{"i":3,"mis":"gen.neighbor","note":"ترك الأثر حاجات الروح ومعنى الحياة."}],"tests":["هرم الأحجار الكبيرة","الحاجة إلى الحب"]},{"n":1036,"lo":"U2","sec":"GS151-PRAC","type":"term","topic":"تعريف التسويف","stem":"أن تقوم بمهمة ذات أولوية منخفضة بدلاً من أن تنجز مهمتك ذات الأولوية العالية، أو الميل لتأجيل وأداء المهام. هذه العبارة تشير إلى مفهوم:","options":["الاستثمار","الوقت","التسويف","الاحتراق"],"answer":2,"why":"ص35: «التسويف هو أن تقوم بمهمة ذات أولوية منخفضة بدلاً من أن تنجز مهمتك ذات الأولوية العالية، أو الميل لتأجيل أداء المهام» — نفس التعريف بالحرف.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الاستثمار إنك تضاعف إنتاجك في نفس الوقت، عكس التسويف."},{"i":1,"mis":"gen.keyword","note":"الوقت مقدار من الزمن، مو سلوك التأجيل."},{"i":3,"mis":"gen.neighbor","note":"الاحتراق نتيجة التسويف ص31، مو تعريفه."}],"tests":["التسويف","تعريف التسويف"]},{"n":1037,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"تقييم البدائل","stem":"البديل الذي لا يتوقع أن تكون له عيوباً أو مزايا هو البديل:","options":["المختلط","الجيد","المجدي","غير المجدي"],"answer":3,"why":"ص58 عيوب ومزايا: البديل غير المجدي (Bland) «ما يتوقع له عيوب أو مزايا».","wrong":[{"i":0,"mis":"gen.neighbor","note":"المختلط (Mixed) تتساوى عيوبه ومزاياه، يعني فيه الاثنين"},{"i":1,"mis":"gen.neighbor","note":"الجيد (Good) مزاياه أكثر من عيوبه"},{"i":2,"mis":"gen.keyword","note":"ما فيه بديل اسمه «المجدي» بالكتاب؛ الصح غير المجدي"}],"tests":["أنواع البدائل حسب العيوب والمزايا"]},{"n":1038,"lo":"U1","sec":"GS151-PRAC","type":"list","topic":"ضوابط الهدف الأكثر فاعلية","stem":"جميع ما يأتي من ضوابط الهدف الفعال ما عدا:","options":["استخدام الورقة والقلم","ترتيب الأولويات","البحث عن رفيق للهدف","عدم مراقبة العواقب"],"answer":3,"why":"ص14 ضابط رقم 10: «راقب المعوقات» وتعلم من أخطائك، فعدم المراقبة عكس الضابط. استخدم الورق (5) ورتب أولوياتك (4) وابحث عن رفيق لهدفك (9) كلها ضوابط.","wrong":[{"i":0,"mis":"gen.neighbor","note":"«استخدم الورق» ضابط رقم 5 ص14"},{"i":1,"mis":"g1.abc-priority","note":"«رتب أولوياتك» ضابط رقم 4 ص13"},{"i":2,"mis":"gen.neighbor","note":"«ابحث عن رفيق لهدفك» ضابط رقم 9 ص14، للتحفيز والمتابعة"}],"tests":["ضوابط الهدف الأكثر فاعلية","راقب المعوقات"]},{"n":1039,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"أنواع المعلومات","stem":"هي المعلومات الخام المتعلقة بموضوع والتي تجمع من مصادر مختلفة ولها ثلاث أنواع هي البيانات الأولية والثانوية والتاريخية","options":["البيانات","المعلومات الكمية","المعلومات الوصفية","التنبؤات"],"answer":0,"why":"ص52 أنواع المعلومات: «البيانات» هي المعلومات الخام المتعلقة بالموضوع وتنجمع من مصادر مختلفة، وأنواعها ثلاثة: أولية وثانوية وتاريخية.","wrong":[{"i":1,"mis":"g3.data-types","note":"الكمية نوع رابع (الكمية والوصفية) تصف بالأرقام"},{"i":2,"mis":"g3.data-types","note":"الوصفية إنشائية تركز على الآراء والأحكام"},{"i":3,"mis":"g3.data-types","note":"التنبؤات تعتمد على الحدس والتخمين، مو معلومات خام"}],"tests":["أنواع المعلومات","البيانات"]},{"n":1040,"lo":"U3","sec":"GS151-PRAC","type":"scenario","topic":"أنواع القرارات","stem":"الذهاب للعمل يومياً يعد مثالاً على القرارات:","options":["المبرمجة","درجة عالية من الخطورة","غير النمطية","غير المبرمجة"],"answer":0,"why":"ص44 جدول أنواع القرارات: من أمثلة القرارات المبرمجة «الذهاب إلى العمل اليومي، شراء الملابس».","wrong":[{"i":1,"mis":"g3.programmed-flip","note":"المبرمجة مخاطرها منخفضة أو منعدمة"},{"i":2,"mis":"g3.programmed-flip","note":"شي يومي متكرر = نمطي روتيني"},{"i":3,"mis":"g3.programmed-flip","note":"غير المبرمجة مثل الزواج واختيار التخصص"}],"tests":["القرارات المبرمجة"]},{"n":1041,"lo":"U2","sec":"GS151-PRAC","type":"scenario","topic":"مصفوفة الوقت – ملعب الاحتراق","stem":"فقدت أجندتك للمواعيد والمهام، واكتشفت مصادفة ان اختبارك في مقرر المهارات غداً، ولديك 7 ساعات فقط للاستذكار، فأنت في ملعب","options":["الرنين","الهروب","الأولويات","الاحتراق"],"answer":3,"why":"ص34: أولوية (ب) المهم العاجل = إدارة الأزمات والضغط. اختبار بكرة وعندك 7 ساعات بس: مهم وعاجل، يعني ملعب الاحتراق.","wrong":[{"i":0,"mis":"g2.urgent-means-important","note":"الرنين عاجل بس غير مهم، والاختبار مهم جداً."},{"i":1,"mis":"gen.neighbor","note":"الهروب لا مهم ولا عاجل."},{"i":2,"mis":"gen.neighbor","note":"الأولويات لما يكون المهم لسه غير عاجل، وهنا الوقت ضاق خلاص."}],"tests":["مصفوفة الوقت","ملعب الاحتراق","المهم العاجل"]},{"n":1042,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"خصائص الهدف الفعال SMART","stem":"يعاب على الهدف «أن أنقص وزني خلال شهر» أنه","options":["غير مرتبط بوقت","غير قابل للقياس","غير واقعي","غير قابل للتحقيق"],"answer":1,"why":"ص13: قابل للقياس يعني الهدف يكون كمي وغالبًا بالأرقام. «أنقص وزني» بدون كم كيلو، فما تقدر تقيس تقدمك. الوقت موجود (خلال شهر).","wrong":[{"i":0,"mis":"gen.detail","note":"فيه وقت واضح: «خلال شهر»"},{"i":2,"mis":"g1.attainable-vs-realistic","note":"إنقاص الوزن شي واقعي، المشكلة إنه ما فيه رقم"},{"i":3,"mis":"g1.attainable-vs-realistic","note":"ممكن يتحقق، بس ما تعرف كم المطلوب بالضبط"}],"tests":["Measurable = كمي","ضابط الدقة في الكمية"]},{"n":1043,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"أنواع البيانات","stem":"هي البيانات التي تتعلق بالموضوع لفترات سابقة أو خبرات سابقة","options":["البيانات التاريخية","البيانات الثانوية","البيانات الكمية","البيانات الأولية"],"answer":0,"why":"ص52 جدول البيانات: التاريخية «ما يتعلق بالموضوع لفترات سابقة أو خبرات سابقة أو أفراد سابقين».","wrong":[{"i":1,"mis":"g3.data-types","note":"الثانوية انجمعت لأغراض ثانية"},{"i":2,"mis":"g3.data-types","note":"الكمية تصف بالأرقام، مو بالزمن"},{"i":3,"mis":"g3.data-types","note":"الأولية تنجمع خصيصاً للموضوع الحين"}],"tests":["البيانات التاريخية","أنواع البيانات"]},{"n":1044,"lo":"U3","sec":"GS151-PRAC","type":"scenario","topic":"أنواع القرارات","stem":"قرر عثمان السفر من أجل الحصول على درجة الدكتوراه في تخصص الجراحة، إن هذا يعد مثالاً على القرار:","options":["المبرمج","المتكرر","غير المبرمج","النمطي"],"answer":2,"why":"ص44: القرار غير المبرمج غير متكرر وغير روتيني ودرجة عدم التأكد فيه عالية ومخاطره مرتفعة، مثل الزواج واختيار التخصص. سفر الدكتوراه من نفس النوع.","wrong":[{"i":0,"mis":"g3.programmed-flip","note":"المبرمج روتيني ومتكرر مثل الذهاب للدوام"},{"i":1,"mis":"g3.programmed-flip","note":"سفر الدكتوراه ما يتكرر"},{"i":3,"mis":"g3.programmed-flip","note":"النمطي = المبرمج الروتيني، وهذا قرار مصيري"}],"tests":["القرارات غير المبرمجة"]},{"n":1045,"lo":"U1","sec":"GS151-PRAC","type":"list","topic":"ضوابط الهدف الأكثر فاعلية","stem":"من ضوابط الهدف الأكثر فعالية:","options":["وضع هدفين في جملة واحدة.","عدم استخدام النفي في صياغة الأهداف","الحد من ترتيب الأولويات.","الاستعانة بالرفقاء في وضع الأهداف."],"answer":1,"why":"ص13 ضابط رقم 2: لا تستعمل النفي في صياغة أهدافك. (كلمة «التقنى» في النسخة غلط طباعي، المقصود «النفي»).","wrong":[{"i":0,"mis":"gen.reversed","note":"الضابط: الهدف الواحد في جملة واحدة، مو هدفين"},{"i":2,"mis":"g1.abc-priority","note":"الضابط «رتب أولوياتك»، مو قلل منها"},{"i":3,"mis":"g1.own-goals","note":"لا تدع أحد يضع لك أهدافك ص14؛ الرفيق للتحفيز والمتابعة بس، مو لوضعها"}],"tests":["عدم استخدام النفي","لا تدع أحد يضع لك أهدافك"]},{"n":1046,"lo":"U2","sec":"GS151-PRAC","type":"scenario","topic":"مصفوفة الوقت – ملعب الأولويات","stem":"سليم أحد الطلاب الذين يدرسون مقرر مهارات الحياة الجامعية ويحتاج لعمل بحث ضمن متطلبات المقرر، حيث يخطط لتسليم البحث بعد أربعة شهور. يُعد هذا الفعل ضمن مصفوفة الوقت مثال على:","options":["الرنين","الهروب","الاحتراق","الأولويات"],"answer":3,"why":"ص34: أولوية (أ) المهم غير العاجل تنجزها بالتخطيط من بدري. البحث مهم للمقرر وباقي له 4 شهور ويخطط له، فهو في ملعب الأولويات.","wrong":[{"i":0,"mis":"g2.urgent-means-important","note":"الرنين أشياء عاجلة غير مهمة، والبحث مهم ومو عاجل."},{"i":1,"mis":"gen.neighbor","note":"الهروب لا مهم ولا عاجل، والبحث متطلب مقرر."},{"i":2,"mis":"gen.neighbor","note":"الاحتراق لو أجله لآخر أسبوع، بس هو مخطط من بدري."}],"tests":["مصفوفة الوقت","ملعب الأولويات","المهم غير العاجل"]},{"n":1047,"lo":"U3","sec":"GS151-PRAC","type":"list","topic":"أركان القرار","stem":"يتكون القرار من أركان منها","options":["النمطية","الروتين","المشكلة","البدائل"],"answer":3,"why":"ص43: أركان القرار ثلاثة: الاختيار الواعي، البدائل المتاحة، الأهداف المرجوة.","wrong":[{"i":0,"mis":"gen.keyword","note":"النمطية وصف للقرار المبرمج، مو ركن"},{"i":1,"mis":"gen.keyword","note":"الروتين وصف للقرار المبرمج، مو ركن"},{"i":2,"mis":"gen.neighbor","note":"المشكلة سبب نتخذ عشانه القرار، بس مو من أركانه الثلاثة"}],"tests":["أركان القرار"]},{"n":1048,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"أركان صانع القرار","stem":"اكمل الفراغ: الشخص الذي لا يملك قوة............. لن ينجح أبدًا في قرارته","options":["المخاطرة","الوقت","الذات","الأهداف"],"answer":0,"why":"ص43 تحت «والمخاطرة»: الكتاب يقول اللي ما عنده «إرادة المخاطرة» ما راح ينجح أبداً في قراره. الدكتور كتبها «قوة» بدل «إرادة» بس المعنى نفسه، والجواب المخاطرة. وهي واحدة من أركان صانع القرار الثلاثة: الصبر، الأفضل، المخاطرة.","wrong":[{"i":1,"mis":"gen.neighbor","note":"الوقت مو من أركان صانع القرار (الصبر، الأفضل، المخاطرة)"},{"i":2,"mis":"gen.neighbor","note":"الذات تخص إدارة الذات، ما لها دخل بالجملة هذي"},{"i":3,"mis":"g3.arkan-mix","note":"الأهداف المرجوة ركن من أركان القرار نفسه، أما الجملة فعن صانع القرار والمخاطرة"}],"tests":["أركان صانع القرار","المخاطرة"]},{"n":1049,"lo":"U1","sec":"GS151-PRAC","type":"concept","topic":"خصائص الهدف الفعال SMART","stem":"نعني بكون الهدف قابلا للقياس","options":["ألا يكون خياليا","أن يرتبط بوقت","أن يكون مناسبا لقدرات الشخص","أن يكون كميا"],"answer":3,"why":"ص13: عشان تتابع تقدمك لازم الأهداف تكون كمية، غالبًا بالأرقام، فيسهل قياسها ومقارنتها بالوضع المطلوب.","wrong":[{"i":0,"mis":"g1.attainable-vs-realistic","note":"«مو خيالي» هذا معنى واقعي Realistic"},{"i":1,"mis":"gen.neighbor","note":"الارتباط بوقت هو Time-bound"},{"i":2,"mis":"g1.attainable-vs-realistic","note":"مناسب لقدراتك = قابل للتحقيق Attainable"}],"tests":["Measurable","حروف SMART"]},{"n":1050,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"طبيعة الوقت – تعويض الوقت","stem":"قول الرسول صلى الله عليه وسلم \"اغتنم خمسا قبل خمس: شبابك قبل هرمك، وصحتك قبل سقمك، وغناك قبل فقرك، وفراغك قبل شغلك، وحياتك قبل موتك\" يشير الحديث الشريف إلى أن من طبيعة الوقت :","options":["نمو الوقت","يجري","محدود","لا يعوض"],"answer":3,"why":"ص21: الحديث جاي تحت «تعويض الوقت»، والكتاب يشرح: نغتنم أوقات الصحة والشباب والفراغ لأنها لو مرّت قد ما ترجع مثلها. يعني الوقت ما يتعوض.","wrong":[{"i":0,"mis":"gen.neighbor","note":"نمو الوقت عن زيادة قيمته بالاستثمار، مو هذا الحديث."},{"i":1,"mis":"gen.neighbor","note":"«يجري» استشهد له الكتاب بآيات «لم يلبثوا إلا ساعة»، مو بهذا الحديث."},{"i":2,"mis":"gen.neighbor","note":"«محدود» عن الـ168 ساعة وإنه ما ينخزن، والحديث تحت التعويض."}],"tests":["طبيعة الوقت","تعويض الوقت","اغتنام الأوقات"]},{"n":1051,"lo":"U2","sec":"GS151-PRAC","type":"term","topic":"تعريف إدارة الوقت","stem":"الاستخدام الأفضل للوقت بالامكانيات المتاحة بطريقة تؤدي إلى تحقيق الإهداف يُسمى إدارة:","options":["الوقت","الفريق","الأعمال","المجموعة"],"answer":0,"why":"ص20 بالبرواز الرمادي: «أما إدارة الوقت فهي الاستخدام الأفضل للوقت بالإمكانيات المتاحة بطريقة تؤدي إلى تحقيق الأهداف».","wrong":[{"i":1,"mis":"gen.keyword","note":"إدارة الفريق ما تنذكر في تعريف الوحدة."},{"i":2,"mis":"gen.keyword","note":"إدارة الأعمال تخصص كامل، مو هذا التعريف."},{"i":3,"mis":"gen.keyword","note":"المجموعة ما لها دخل، التعريف كله عن الوقت."}],"tests":["تعريف إدارة الوقت"]},{"n":1052,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"أنواع الأهداف من حيث الزمن","stem":"التحقت بمدرسة تحفيظ القران الكريم لأتم حفظي في مدة لا تتجاوز 2 سنة، نوع الهدف","options":["طويل المدى","متوسط المدى","غاية كبرى","قصير المدى"],"answer":3,"why":"ص9: القصير المدى زمن تنفيذه أقل من 3 سنين، والهدف هنا سنتين.","wrong":[{"i":0,"mis":"g1.long-term-span","note":"الطويل فوق 10 سنين"},{"i":1,"mis":"gen.neighbor","note":"المتوسط من 3 (أو 5) إلى 10 سنين، وسنتين أقل"},{"i":2,"mis":"g1.ghaya-level","note":"الغاية أعلى درجات الأهداف، مو تصنيف زمني"}],"tests":["الأهداف قصيرة المدى < 3 سنوات"]},{"n":1053,"lo":"U1","sec":"GS151-PRAC","type":"list","topic":"تحقيق الأهداف: على طريق التنفيذ","stem":"على طريق تنفيذ الأهداف ينبغي أن :","options":["تكتسب طاقة للتنفيذ","البحث عن مرشد","تجزئ الهدف","تسجل كل نجاحاتك السابقة"],"answer":3,"why":"ص15 تحت عنوان «ثانياً: على طريق التنفيذ» أول بند: سجل كل نجاحاتك السابقة في نفس مجال هدفك حتى لو صغيرة. الخيارات الثانية كلها من القائمة الأولى «أولاً: حوّل الأهداف لأنشطة» (ص14–15)، فالسؤال يختبر إنك تفرّق بين القائمتين.","wrong":[{"i":0,"mis":"gen.neighbor","note":"اكتسب طاقة من قائمة «حوّل الأهداف لأنشطة» ص14، مو «على طريق التنفيذ»"},{"i":1,"mis":"gen.neighbor","note":"ابحث عن مرشد بند 4 في قائمة «حوّل الأهداف لأنشطة» ص15"},{"i":2,"mis":"gen.neighbor","note":"جزّئ الهدف أول خطوة في «حوّل الأهداف لأنشطة» ص14"}],"tests":["على طريق التنفيذ","التفريق بين القائمتين"]},{"n":1054,"lo":"U1","sec":"GS151-PRAC","type":"list","topic":"خطوات وضع الأهداف","stem":"يعد العصف الذهني الخطوة...... من خطوات وضع الأهداف","options":["الأولى","الثالثة","الثانية","الرابعة"],"answer":1,"why":"ص10–11: الأولى أهداف بعيدة المدى، الثانية أهداف لكل مجال، الثالثة استخدم العصف الذهني، الرابعة أهداف قريبة المدى.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الأولى: ضع أهداف بعيدة المدى"},{"i":2,"mis":"gen.neighbor","note":"الثانية: أهداف لكل مجال. وانتبه، العصف الذهني ثاني خطوة في «تحويل الأهداف لأنشطة» ص14 مو في خطوات الوضع"},{"i":3,"mis":"g1.short-vs-near","note":"الرابعة: ضع الأهداف قريبة المدى (خمس سنين)"}],"tests":["ترتيب خطوات وضع الأهداف الست"]},{"n":1055,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"عوامل تضييع الوقت","stem":"من عوامل تضييع الوقت","options":["حضور الدورات التدريبية","العمل في الأعمال التطوعية","عدم وجود أهداف أو خطط","قضاء وقت في زيارة الأقارب"],"answer":2,"why":"ص34: «من عوامل تضييع الأوقات: 1- عدم وجود أهداف أو خطط»، وهذا يخلي حياة الإنسان متخبطة عشوائية.","wrong":[{"i":0,"mis":"gen.reversed","note":"الدورات تبع حاجة التعلم، استثمار للوقت مو تضييع."},{"i":1,"mis":"gen.reversed","note":"التطوع يدخل في ترك الأثر، مو تضييع."},{"i":3,"mis":"gen.reversed","note":"صلة الأقارب من العلاقات (حاجة الحب)، مو من العوامل المذكورة."}],"tests":["مضيعات الوقت","عوامل تضييع الأوقات"]},{"n":1056,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"أنواع المعلومات","stem":"البيانات التي تصف الموضوع في صورة رقمية قابلة للقياس هي","options":["البيانات الكمية","البيانات التاريخية","البيانات الثانوية","البيانات الأولية"],"answer":0,"why":"ص53: الكمية «صورة رقمية قابلة للقياس (منحنيات وجداول)»، والوصفية إنشائية.","wrong":[{"i":1,"mis":"g3.data-types","note":"التاريخية تصنيف حسب الزمن (فترات سابقة)"},{"i":2,"mis":"g3.data-types","note":"الثانوية تصنيف حسب سبب الجمع"},{"i":3,"mis":"g3.data-types","note":"الأولية تنجمع خصيصاً للموضوع، ممكن تكون رقمية أو لا"}],"tests":["البيانات الكمية والوصفية"]},{"n":1057,"lo":"U2","sec":"GS151-PRAC","type":"scenario","topic":"مصفوفة الوقت – ملعب الرنين","stem":"حينما تلبي دعوة على العشاء، في يوم مزدحم بالواجبات والأعمال التي تحتاج إلى وقت طويل، فأنت في ملعب","options":["المهم غير العاجل","غير المهم العاجل","غير المهم غير العاجل","المهم العاجل"],"answer":1,"why":"ص31–32: الرنين = غير المهم العاجل، أشياء تلحّ عليك وتستعجلك وهي مو مهمة، ومن أمثلته «الزيارة غير المرتبة وغير المحددة». دعوة العشا بيوم مليان واجبات بالضبط هذا.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المهم غير العاجل للأولويات زي واجباتك المتكدسة، مو العشا."},{"i":2,"mis":"gen.neighbor","note":"الدعوة لها وقت محدد الليلة، فهي عاجلة، مو هروب."},{"i":3,"mis":"g2.urgent-means-important","note":"كونها عاجلة ما يخليها مهمة، والمهم فعلاً واجباتك."}],"tests":["مصفوفة الوقت","ملعب الرنين","غير المهم العاجل"]},{"n":1058,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"النظرية التوفيقية","stem":"تؤخذ القرارات المهمة والاستراتيجية وذات الأثر البعيد وفقا للنظرية التوفيقية على أساس:","options":["حدسي","تراكمي","عقلاني","حسي"],"answer":2,"why":"ص46: القرارات الأساسية (long range) المهمة والاستراتيجية «تؤخذ على أساس عقلاني».","wrong":[{"i":0,"mis":"g3.theorist-swap","note":"الحدس والفطرة أساس نظرية ليندبلوم، مو الأساسية عند إتزيوني"},{"i":1,"mis":"g3.basic-secondary","note":"التراكمي للقرارات الثانوية ذات الأثر القصير"},{"i":3,"mis":"gen.neighbor","note":"ما فيه أساس حسي بالنظرية"}],"tests":["النظرية التوفيقية","القرارات الأساسية"]},{"n":1059,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"صفات المضيعين للوقت","stem":"الاشتغال بالأمور الثانوية، وإعطاء العمل البسيط فوق ما يستحق من الجهد، وتضييع الساعات الطوال بغير عمل، وتراكم أكثر من عمل في وقت واحد. هذه الصفات تنطبق على الأشخاص:","options":["المضيعون للوقت","السعداء","الناجحون","المرتبون"],"answer":0,"why":"ص34: «معظم الذين يضيعون وقتهم يشتركون في صفات أربعة»، وهي نفس الأربع المذكورة بالسؤال بالترتيب.","wrong":[{"i":1,"mis":"g2.success-vs-happiness","note":"السعداء يقضون أوقاتهم في ملعب (1)، عكس هالصفات."},{"i":2,"mis":"g2.success-vs-happiness","note":"الناجحون يقضون أوقاتهم في ملعب (1) و(2)، مو بالثانويات."},{"i":3,"mis":"gen.reversed","note":"المرتب عكس المضيع؛ «غير منظم» من صفات المضيع."}],"tests":["مضيعات الوقت","صفات المضيع للوقت"]},{"n":1060,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"هرم الأحجار الكبيرة – القمة","stem":"الحاجات التي تقع في قمة هرم الأحجار الكبيرة، هي:","options":["الحب","ترك الأثر","الحياة","التعلم"],"answer":1,"why":"ص38: الهرم من القاعدة للقمة: الحياة، الحب، التعلم، ترك الأثر. فبالقمة ترك الأثر (حاجات الروح ومعنى الحياة).","wrong":[{"i":0,"mis":"g2.pyramid-order","note":"الحب ثاني من تحت."},{"i":2,"mis":"g2.pyramid-order","note":"الحياة بالقاعدة مو بالقمة."},{"i":3,"mis":"g2.pyramid-order","note":"التعلم تحت القمة مباشرة، مو القمة نفسها."}],"tests":["هرم الأحجار الكبيرة","ترك الأثر","ترتيب الحاجات"]},{"n":1061,"lo":"U2","sec":"GS151-PRAC","type":"scenario","topic":"مصفوفة الوقت – ملعب الأولويات","stem":"قرر محمد استثمار وقته من خلال التخطيط الاستراتيجي وإدارة المستقبل لإنجاز أهدافه في الحياة بحسن التخطيط والتنظيم. إن تركيز محمد منصب على المهمات التي تقع في مصفوفة الوقت ضمن مربع:","options":["الأولويات","الهروب","الرنين","الاحتراق"],"answer":0,"why":"ص34: أولوية (أ) المهم غير العاجل نصوغها «من خلال التخطيط الاستراتيجي وإدارة المستقبل». هذا بالضبط ملعب الأولويات.","wrong":[{"i":1,"mis":"gen.neighbor","note":"الهروب أعمال لا مهمة ولا عاجلة، مو تخطيط استراتيجي."},{"i":2,"mis":"g2.urgent-means-important","note":"الرنين استجابة لأشياء عاجلة غير مهمة، عكس التخطيط."},{"i":3,"mis":"gen.neighbor","note":"الاحتراق = إدارة الأزمات بأسلوب المطافئ بدون تخطيط."}],"tests":["مصفوفة الوقت","أولوية (أ)","التخطيط الاستراتيجي"]},{"n":1062,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"أنواع الأهداف من حيث الزمن","stem":"«أن أحفظ 10 آيات من القران الكريم كل يوم بعد صلاة الفجر»، نوع الهدف","options":["متوسط المدى","إجرائي ذكي","طويل المدى","قصير المدى"],"answer":1,"why":"ص9: أي نشاط يومي أو أسبوعي أو شهري = هدف إجرائي. «كل يوم بعد الفجر» نشاط يومي، وفيه رقم (10 آيات) ووقت محدد فهو كمان ذكي SMART ص12. القصير المدى هو الهدف الأكبر (أقل من 3 سنين) اللي ينقسم لهالأنشطة اليومية.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المتوسط مرتبط بمرحلة 3–10 سنين"},{"i":2,"mis":"g1.long-term-span","note":"الطويل أهداف عمر فوق 10 سنين"},{"i":3,"mis":"g1.operational-todo","note":"النشاط اليومي اسمه إجرائي، القصير هو الهدف الأكبر اللي يتقسم له"}],"tests":["الهدف الإجرائي","SMART"]},{"n":1063,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"إنتاج الأفكار","stem":"من أدوات إنتاج البدائل أثناء عملية صناعة القرار:","options":["العصف الذهني","الاختبار","التجربة","الاستبانة"],"answer":0,"why":"ص57 أدوات إنتاج الأفكار: أهمها طريقة أوسبورن (العصف الذهني Brain-Storming).","wrong":[{"i":1,"mis":"gen.neighbor","note":"الاختبار مو من أدوات إنتاج الأفكار بالكتاب"},{"i":2,"mis":"gen.neighbor","note":"التجربة والخطأ أسلوب المحافظ، مو أداة توليد بدائل"},{"i":3,"mis":"g3.tool-mix","note":"الاستبانة أداة لجمع البيانات الأولية ص52"}],"tests":["العصف الذهني","أدوات إنتاج الأفكار"]},{"n":1064,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"أنواع الأهداف من حيث الزمن","stem":"أخطط لدخول تخصص محاسبة بعد أن أجتاز اختبار المرحلة الثانوية هذا العام، نوع الهدف:","options":["غاية كبرى","قصير المدى","طويل المدى","متوسط المدى"],"answer":1,"why":"ص9: القصير المدى زمن تنفيذه أقل من 3 سنين، ودخول التخصص بيصير خلال هالسنة. المتوسط يغطي مرحلة كاملة زي الجامعة كلها (3 أو 5 لـ10 سنين)، أما هنا الهدف بس إنك تدخل التخصص، مو إنك تخلص الجامعة. وهو مو إجرائي لأنه مو نشاط يومي أو أسبوعي.","wrong":[{"i":0,"mis":"g1.ghaya-level","note":"الغاية أعلى درجات الأهداف (مرادف للهدف)، مو تصنيف زمني"},{"i":2,"mis":"g1.long-term-span","note":"الطويل فوق 10 سنين"},{"i":3,"mis":"gen.neighbor","note":"المتوسط يغطي مرحلة كاملة زي الجامعة (3–10 سنين)، أما دخول التخصص فخلال سنة"}],"tests":["قصير المدى vs متوسط المدى"]},{"n":1065,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"أنواع الأهداف من حيث الزمن","stem":"الإعداد لدورة لمدة شهر هدف:","options":["متوسط المدى","طويل","إجرائي","قصير المدى"],"answer":2,"why":"ص9 حرفياً: الأهداف الإجرائية = أهداف صغيرة تصير مجرد أنشطة شهرية أو أسبوعية أو يومية. الإعداد لدورة مدتها شهر نشاط شهري، فهو إجرائي. صح إن الشهر أقل من 3 سنين، بس الكتاب يحط الأنشطة الشهرية تحت الإجرائي بالاسم، والقصير هو الهدف الأكبر اللي يتقسم لها (رسمة ص9). القاعدة: يوم/أسبوع/شهر = إجرائي.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المتوسط 3–10 سنين"},{"i":1,"mis":"g1.long-term-span","note":"الطويل فوق 10 سنين"},{"i":3,"mis":"g1.operational-todo","note":"شهر واحد يدخل في «الأنشطة الشهرية» = إجرائي، القصير هو الهدف الأكبر (أقل من 3 سنين)"}],"tests":["الهدف الإجرائي (شهري/أسبوعي/يومي)"]},{"n":1066,"lo":"U2","sec":"GS151-PRAC","type":"list","topic":"علاج التسويف","stem":"ضع وقتًا محددًا للانتهاء من كل مهمة، خذ على نفسك عهدًا بعدم تأجيل الأعمال، شجع نفسك بنفسك...الإرشادات السابقة تساعد في:","options":["إدارة فريق العمل","حسن إدارة الوقت","التخطيط للأهداف الفعالة","علاج التسويف والتأجيل"],"answer":3,"why":"ص35–36: تحت عنوان «كيف نقضي على التسويف»: 1- ضع وقتاً محدداً للانتهاء من كل مهمة، 2- خذ على نفسك عهداً بعدم تأجيل الأعمال، 4- شجع نفسك… فهي علاج التسويف.","wrong":[{"i":0,"mis":"gen.keyword","note":"ما فيه شي عن فريق عمل، كلها نصايح لنفسك."},{"i":1,"mis":"gen.partial","note":"صح إنها تخدم إدارة الوقت عموماً، بس الكتاب حاطها بالتحديد لعلاج التسويف."},{"i":2,"mis":"gen.neighbor","note":"ضوابط الهدف الفعال من وحدة الأهداف، مو هذي القائمة."}],"tests":["التسويف","علاج التسويف"]},{"n":1067,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"الناس أمام المشكلات","stem":"اليأس والتخبط عند حل المشكلة يؤدي إلى","options":["حل المشكلة بسرعة","حل المشكلة ببطء","التعايش مع المشكلة","تعقيد المشكلة أكثر"],"answer":3,"why":"ص48: الصنف الثاني يئسوا من كل حل «واستمروا يتخبطون في حبال المشكلة حتى تشابكت وتعقدت».","wrong":[{"i":0,"mis":"gen.reversed","note":"اليأس ما يجيب حل أصلاً، لا سريع ولا بطيء"},{"i":1,"mis":"gen.reversed","note":"الكتاب يقول يضيعون وقتهم بالدعاية للمشكلة بدون حل"},{"i":2,"mis":"gen.neighbor","note":"التعايش وصف الصنف الأول المستهترين (لا مشكلة)"}],"tests":["الناس أمام المشكلات","تضخيم المشكلة"]},{"n":1068,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"مصفوفة الوقت – الوصية الذهبية","stem":"المربع المناسب من مصفوفة الوقت لمن يريد أن ينظم وقته ويحقق أهدافه هو","options":["غير مهم وعاجل","المهم والعاجل","غير مهم وغير عاجل","مهم وغير عاجل"],"answer":3,"why":"ص34: الوصية الذهبية: استثمر معظم الوقت في أولوية (أ) = المهم غير العاجل، لأن نتايجها بعيدة المدى وتنجزها بالتخطيط.","wrong":[{"i":0,"mis":"g2.urgent-means-important","note":"غير المهم العاجل (الرنين) لازم نقلل منه، مو نركز عليه."},{"i":1,"mis":"gen.neighbor","note":"المهم العاجل (الاحتراق) ناخذ منه جزء بس، والتركيز الأكبر على (أ)."},{"i":2,"mis":"gen.reversed","note":"غير المهم غير العاجل (الهروب) هو اللي نتخلص منه."}],"tests":["مصفوفة الوقت","الوصية الذهبية","أولوية (أ)"]},{"n":1069,"lo":"U3","sec":"GS151-PRAC","type":"list","topic":"أساليب اتخاذ القرار","stem":"من مشكلات اتخاذ القرار بالأسلوب المحافظ","options":["كثرة البدائل","الاعتماد على المزاجية","قصور الميزانيات","صعوبة تحديد المشكلة"],"answer":2,"why":"ص45: مشكلات اتخاذ القرار بالأسلوب المحافظ: قيود الوقت، ضعف المعلومات، قصور الميزانيات، قلة الطاقة البشرية التنفيذية.","wrong":[{"i":0,"mis":"gen.neighbor","note":"صعوبة التعامل مع عدد كبير من البدائل اعتراض على الأسلوب العلمي ص46"},{"i":1,"mis":"gen.neighbor","note":"الحالة المزاجية والحكم الشخصي اعتراض على الأسلوب العلمي ص46"},{"i":3,"mis":"gen.neighbor","note":"صعوبة تحديد المشكلة من اعتراضات الأسلوب العلمي ص46"}],"tests":["مشكلات الأسلوب المحافظ"]},{"n":1070,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"النظرية التوفيقية","stem":"أسلوب اتخاذ القرار الذي يجمع بين النظريتين التراكمية والعقلية هو:","options":["الأسلوب العلمي","النظرية التوفيقية","المحافظ","القرار المرضي"],"answer":1,"why":"ص46: إتزيوني اقترح «النموذج المختلط أو النظرية التوفيقية» وتسعى للتوفيق بين النظرية العقلانية والنظرية التراكمية.","wrong":[{"i":0,"mis":"gen.partial","note":"العلمي عقلاني بس"},{"i":2,"mis":"gen.partial","note":"المحافظ تراكمي بس"},{"i":3,"mis":"g3.economic-vs-admin","note":"المرضي شكل ثاني من العلمي (الرجل الإداري)"}],"tests":["النظرية التوفيقية","إتزيوني"]},{"n":1071,"lo":"U2","sec":"GS151-PRAC","type":"term","topic":"مصفوفة الوقت – ملعب الاحتراق","stem":"يسمى ملعب الوقت الخاص بالأزمات والمهام الطارئة:","options":["الرنين.","الهروب.","الاحتراق","الأولويات."],"answer":2,"why":"ص34: أولوية (ب) المهم العاجل = الأعمال اللي ننجزها من خلال إدارة الأزمات بأسلوب المطافئ، وهذا ملعب الاحتراق.","wrong":[{"i":0,"mis":"g2.urgent-means-important","note":"الرنين عاجل بس غير مهم، مو أزمات."},{"i":1,"mis":"gen.neighbor","note":"الهروب لا مهم ولا عاجل."},{"i":3,"mis":"g2.priority-a-urgent","note":"الأولويات (أ) مهمة بس مو عاجلة، تنجز بالتخطيط مو بالطوارئ."}],"tests":["مصفوفة الوقت","ملعب الاحتراق","أولوية (ب)"]},{"n":1072,"lo":"U1","sec":"GS151-PRAC","type":"scenario","topic":"أدوار الحياة (مجالات الأهداف)","stem":"عندما تنوي الذهاب لأداء فريضة الحج، إن ذلك ينتمي إلى أحد مجالات الأهداف، هو:","options":["المهني","الأسري","الروحي","المادي"],"answer":2,"why":"ص11: الدور الروحي = علاقة جيدة مع الله، ضع أهداف لتمتين العلاقة وإتمام فروضها ونوافلها. الحج فريضة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المهني عن المستوى اللي تبي توصله في مهنتك"},{"i":1,"mis":"gen.neighbor","note":"الأسري عن أسرتك وكيف ترعاها"},{"i":3,"mis":"gen.neighbor","note":"المادي عن دخلك المتوقع وعلاقته بأهدافك المهنية"}],"tests":["الدور الروحي"]},{"n":1073,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"أساليب اتخاذ القرار","stem":"التراكمية ميزة من مميزات اتخاذ القرار بالأسلوب:","options":["العلمي","التوافقي","المرضي","المحافظ"],"answer":3,"why":"ص45: الأسلوب المحافظ «له ميزة عظيمة وهي التراكمية»، صاحبه يبدأ من حيث انتهى الآخرون.","wrong":[{"i":0,"mis":"gen.reversed","note":"العلمي عقلاني يدور الأمثل، مو تراكمي"},{"i":1,"mis":"gen.partial","note":"التوفيقي ياخذ التراكمي للقرارات الثانوية بس، والميزة بالكتاب منسوبة للمحافظ"},{"i":2,"mis":"g3.economic-vs-admin","note":"المرضي شكل من العلمي يرضى بالمناسب"}],"tests":["الأسلوب المحافظ","التراكمية"]},{"n":1074,"lo":"U3","sec":"GS151-PRAC","type":"list","topic":"خريطة حل المشكلات","stem":"أول خطوة في عملية إصدار القرار ضمن خريطة حل المشكلات واتخاذ القرار هي:","options":["المتابعة والتقييم","التنفيذ","المرونة","المواجهة"],"answer":1,"why":"ص48 الخريطة فيها 9 خطوات في 3 مراحل. «إصدار القرار» اسم المرحلة الثالثة بالضبط، وأول خطوة فيها السابعة: التنفيذ، بعدها الثامنة المتابعة والتقييم، وبعدها التاسعة المرونة. انتبه: المواجهة أول خطوة في الخريطة كلها (المرحلة الأولى «ما المشكلة؟»)، بس السؤال يسأل عن مرحلة إصدار القرار.","wrong":[{"i":0,"mis":"g3.stage-order","note":"المتابعة والتقييم الخطوة الثامنة، يعني الثانية في مرحلة إصدار القرار"},{"i":2,"mis":"g3.stage-order","note":"المرونة التاسعة، آخر خطوة في المرحلة وفي الخريطة كلها"},{"i":3,"mis":"g3.stage-order","note":"المواجهة أول خطوة في المرحلة الأولى (ما المشكلة؟)، مو في مرحلة إصدار القرار"}],"tests":["خريطة حل المشكلات","مرحلة إصدار القرار"]},{"n":1075,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"أدوات تحليل المعلومات","stem":"أداة تحليل وعرض المعلومات التي تعد تعبير مختصر عن مراجعة وتقييم البرامج هي","options":["المدرج التكراري","خريطة بيرت","خريطة التدفق","خريطة باي"],"answer":1,"why":"ص55: مصطلح «بيرت» PERT تعبير مختصر عن أسلوب مراجعة وتقييم البرامج Program Evaluation and Review Technique.","wrong":[{"i":0,"mis":"g3.tool-mix","note":"المدرج التكراري أعمدة توضح توزيع الخصائص"},{"i":2,"mis":"g3.tool-mix","note":"التدفق تظهر المدخلات والأنشطة ونقاط القرار بأسهم"},{"i":3,"mis":"g3.tool-mix","note":"باي توضح علاقة الجزء بالكل"}],"tests":["خريطة بيرت","أدوات تحليل وعرض المعلومات"]},{"n":1076,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"أنواع البيانات","stem":"البيانات التي جمعت لأغراض أخرى لا تتعلق بالموضوع وتصلح للاستخدام تسمى:","options":["بيانات تاريخية","بيانات ثانوية","مصادر","بيانات أولية"],"answer":1,"why":"ص52 جدول البيانات: الثانوية «جمعت لأغراض أخرى وتصلح للموضوع... ما تتعلق بالموضوع مباشرة ولكن تصلح للاستفادة منها».","wrong":[{"i":0,"mis":"g3.data-types","note":"التاريخية لفترات أو خبرات سابقة"},{"i":2,"mis":"gen.neighbor","note":"«مصادر» مو نوع من البيانات بالكتاب"},{"i":3,"mis":"g3.data-types","note":"الأولية تنجمع خصيصاً للموضوع"}],"tests":["البيانات الثانوية"]},{"n":1077,"lo":"U2","sec":"GS151-PRAC","type":"concept","topic":"أعراض التسويف","stem":"قضاء فترة طويلة في احتساء القهوة يُعد من أعراض:","options":["الرنين","هدر الوقت","الاحتراق","التسويف"],"answer":3,"why":"ص35: «أعراض التسويف: 2- قضاء فترات طويلة في تناول القهوة والشاي أو وجبة الغداء…» — فهو عرض للتسويف.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الرنين أشياء خارجية عاجلة تجذبك زي التلفون، مو جلسة قهوة."},{"i":1,"mis":"gen.partial","note":"صح إنه يهدر الوقت، بس الكتاب ذكره بالاسم تحت أعراض التسويف."},{"i":2,"mis":"gen.neighbor","note":"الاحتراق نتيجة التسويف بعدين، مو العرض نفسه."}],"tests":["التسويف","أعراض التسويف"]},{"n":1078,"lo":"U3","sec":"GS151-PRAC","type":"concept","topic":"احذر أن تتخذ القرار","stem":"من المواقف التي ينبغي أن نحذر فيها من اتخاذ القرار","options":["في المواقف الروتينية","عندما تكون قد جمعت معلومات كافية حول الموضوع","عندما يكون قرارك رد فعل لما تسمعه","في المشكلات النمطية"],"answer":2,"why":"ص47 «احذر أن تتخذ القرار»: الموقف العاشر «قرارك رد فعل لما تسمعه».","wrong":[{"i":0,"mis":"gen.neighbor","note":"المواقف الروتينية مو من العشرة؛ هذي قرارات مبرمجة عادية"},{"i":1,"mis":"gen.reversed","note":"الكتاب يحذر لما «ما تهتم بالمعلومات»، والمعلومات الكافية شي زين"},{"i":3,"mis":"gen.neighbor","note":"المشكلات النمطية مو من مواقف التحذير"}],"tests":["مواقف احذر أن تتخذ القرار"]},{"n":1079,"lo":"U3","sec":"GS151-PRAC","type":"term","topic":"أساليب اتخاذ القرار","stem":"يسمى هذا الأسلوب في اتخاذ القرار النموذج الراشد","options":["الأسلوب المحافظ","الأسلوب العلمي","القرار المرضي","النظرية التوفيقية"],"answer":1,"why":"ص45: «ثانياً: الأسلوب العلمي: سماه الدكتور سيد عليوة النموذج الراشد» وهو سلوك الرجل الاقتصادي.","wrong":[{"i":0,"mis":"gen.neighbor","note":"المحافظ لليندبلوم ويقوم على التجربة والخطأ"},{"i":2,"mis":"g3.economic-vs-admin","note":"المرضي = الرجل الإداري، والراشد = العلمي (الرجل الاقتصادي)"},{"i":3,"mis":"g3.theorist-swap","note":"التوفيقية لإتزيوني ويسمونها النموذج المختلط"}],"tests":["الأسلوب العلمي","النموذج الراشد"]},{"n":1124,"lo":"U1","sec":"GS151-PRAC","type":"term","topic":"مرادفات الهدف","stem":"أعلى درجات الأهداف وأكثرها طموحًا هو:","options":["الغاية","الغرض","الأمنية","الحلم"],"answer":0,"why":"ص9: الغاية هي أعلى درجات الأهداف وأكثرها طموح.","wrong":[{"i":1,"mis":"gen.keyword","note":"«الغرض» مو من مرادفات الهدف في الكتاب أصلًا"},{"i":2,"mis":"g1.umniya-vs-hulm","note":"الأمنية شي تبيه بس بدون برنامج عملي"},{"i":3,"mis":"g1.umniya-vs-hulm","note":"الحلم شي تستبعد يصير، مو أعلى درجة"}],"tests":["الغاية","مرادفات الهدف"]}]};
